quests[49455] = { id = 49455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leather - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
