quests[49464] = { id = 49464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurolisk Tails", description = "Among the upper echelons of Kul Tiran society, there is one cuisine that escapes all but the most determined of chefs. Nobles will pay exorbitant amounts to have just a taste of this delicacy, spiced and cooked to one's delight.\n\nI speak, of course, of the saurolisk tail.\n\nI must discover the finest method of cooking this sought after comestible! Boiled? Braised? Poached? Perhaps steamed or blanched is the most appropriate method!\n\nI will, of course, need a few tails to test.", objectives = "Collect 5 Saurolisk Tails from Lichenjaw Saurolisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49465] = { id = 49465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximizing Resources", description = "Let me tell you a thing about my employees.\n\nThey're always blowing things out of proportion! I give them a good job with a steady wage and what do they do? They try to make excuses as to why they can't work!\n\nThey say the trees have come alive. Trees? Walking and fighting? If you're going to lie, at least make it more believable.\n\nIf they want to convince me, I'm going to need cold hard proof.", progress = "I give them an honest job with good pay. This is the thanks I get?", completion = "<Algerson examines the skull.>\n\nNow this... this is something! Why are my workers running, they should be harvesting!\n\nWe could make a killing with these!", objectives = "Collect 5 Wood-Adorned Skulls in Algerson Lumber Yard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49467] = { id = 49467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witch of the Woods", description = "A... a witch?!\n\nI uh... I would love to help you, truly I would but... I must report to my father.\n\nWhy don't you go stop the witch yourself? For a brave adventurer like you, a witch should be no problem.\n\nI'm sure my father would reward you greatly!", progress = "My son told me about the witch, {name}. I've come up here to take care of her! If you want something done right, you need to do it yourself.", completion = "<Maynard studies the locket.>\n\nThat ungrateful woman!", objectives = "Kill the Witch of the Woods in Fernwood Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49468] = { id = 49468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Required Webinar", description = "I'm not surprised some of the workers stayed in the woods, even amidst the beasts. While he won't admit it, some of father's workers are extremely dedicated.\n\nAnd now they're trapped by the spiders!\n\nPerhaps they have information about what is going on here. Free them from their webbings and see what they know!", completion = "A witch?! This is all because of a witch?!", objectives = "Free 5 Webbed Lumberjacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49472] = { id = 49472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Titanic Effort", description = "Illidan may have forced fate's hand, but bringing Argus so near to Azeroth has accelerated the reaction triggered by the Nightwell's collapse.\n\nI believe the Legion's actions on Argus are further destabilizing the powers we've drawn upon unknowingly for many years.\n\nIt is clear that further studies are required.", progress = "Illidan may believe that no price is too high to pay for banishing the Legion, but fate might prove him wrong.", completion = "The changes this substance has undergone since the Vindicaar departed for Argus are alarming.\n\nWhat will the outcome mean for Azeroth? I fear this to be an ill omen, {name}.", objectives = "Bring 50 Wakening Essence to Arcanomancer Vridiel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49473] = { id = 49473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Titanic Effort", description = "The reaction's intensity is accelerating by the day. We may win the fight against the Legion only to lose something very dear to us.\n\nIs this a portent of some greater upheaval to come? What fate awaits our world, {name}?\n\nI will seek answers at my forge, as I have done all my life. Your answers, I suspect, lie elsewhere.", progress = "If I do not soon discover the underlying cause of this disturbance, I fear we may find ourselves too far down the path to turn back.", completion = "Take this. May it aid your efforts to stop the Legion... and to save our world.", objectives = "Bring 50 Wakening Essence to Arcanomancer Vridiel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49474] = { id = 49474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cursed Shard", description = "<A unnatural metallic shard catches your eye as it shifts from color to color. At your touch, one end of the shard swells in size before melting away. Droplets hit the ground with a hiss and a noxious stench invades your nostrils.\n\nSomeone in Dalaran who works with metals should be able to tell you more.>", completion = "The Betrayer lives up to his name once more.", objectives = "Bring the Cursed Shard to Arcanomancer Vridiel in Dalaran on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49477] = { id = 49477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surprise Backup", description = "<You find a torn Horde missive on the ground...\n\nIt appears that a group of forsaken, led by a man named Chadwick Paxton, were sent here to investigate Nazmir.\n\nYou're unable to discern why they were sent here, but there are coordinates that indicate where they were going.\n\nYou may be able to find the scouts at the coordinates and enlist their aid in fighting the blood trolls.>", completion = "Oh. Hello there, fancy meeting you out here in a swamp. Yes, I'm Chadwick Paxton, or approximately half of him. Care to help?", objectives = "Find Chadwick Paxton, leader of the Forsaken Scouting Party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49479] = { id = 49479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Didn't Stop to Think if They Should", description = "The sethrak seem to believe there's something in Nazmir that can unlock the destructive power of this gem.\n\nWe don't have that, but we have the next best thing. An insane warlock who is willing to experiment with magic.\n\nSpeak with Ingrid and have her begin the process to unlock the true power of this gem.", progress = "Just be careful around Ingrid, she can get a little carried away.", completion = "That gem appears ready to do some damage. Let's just... point it elsewhere, for now.", objectives = "Have Ingrid empower the Skycaller Gem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49488] = { id = 49488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal'gurub", description = "My prophet is a loyal servant, but he has his own ideas of how things must be.\n\nI am sending him to Tal'gurub to deal with a mess of his own making. One of his pupils, a witch doctor by de name of Vol'jamba, has taken de Gurubashi enclave as his own and has ousted my guards.\n\nMeet Zul at Tal'gurub and ensure dis nuisance is dealt with. Do not let him get... distracted.", completion = "Ah, yes, my new escort!\n\nYou are here to enforce de king's will. I would hate for ol' Rastakhan to become disappointed with you, especially after your performance in Stormwind.", objectives = "Meet Zul the Prophet in Tal'gurub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49489] = { id = 49489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Needs a Little Body", description = "I am here primarily to deal with my wayward student. His followers, however, I will leave to you.\n\nI have seen a possible future dat is... concerning. Rivers running red with poison, dead filling de streets. And dese... \"Jambani\" asserting themselves as de new rulers of Zuldazar. Dis cannot come to pass.\n\nFortunately for you, I know how to avoid dat fate. I think you will find their cauldrons are missing one key ingredient.\n\n<He stares at you.>\n\nSomething to give it a little body, perhaps?", progress = "We would not want dem to forego a crucial ingredient, would we?", completion = "Fight fire with fire, dey say. Or in dis case, poison with idiots who chew de ankles of their betters.", objectives = "\"Improve\" 2 concoctions prepared by the Atal'Jamba acolytes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49490] = { id = 49490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Urn of Voices", description = "Vol'jamba does possess de Sight, and so even now he is taking precautions against us.\n\nRegrettably his vision is incomplete. You will help me prepare for his demise and deal with his followers simultaneously. De tool you will use is called de Urn of Voices.\n\nTake it and venture into Tal'gurub. Slay his followers, destroy their golems and masks. Their spirits, once released, will fill de urn.\n\nOh, and try not to die while holding it. De Urn of Voices is not discerning.", progress = "Vol'jamba will pay for his transgressions.", completion = "All according to plan. Do not worry for dem... dis was always their fate.", objectives = "Collect 30 Ounces of Soul from enemies within Tal'gurub.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49491] = { id = 49491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel for the Voodoo", description = "Dere be no time! Dey be draining our spirits... using us... dark voodoo...\n\n<Loa Priestess Izita's spirit grows dim, and her voice is soft and distant.>\n\nDa totems... burn dem...\n\nDen we be free...!", progress = "<The brazier burns brightly.>", completion = "<As the fire chews away at the totems, Gurubashi spirits rise from the ashes.>", objectives = "Collect 8 Voodoo Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49492] = { id = 49492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrogance of Vol'jamba", description = "Vol'jamba thinks his Sight has surpassed mine. I warned against such arrogance many years ago, but we see how well he listened.\n\n<Zul chuckles.>\n\nNo doubt he will attempt to deter us as we encroach upon his sanctum. Listen if you like, but remember dat he is desperate to save himself. His truth is distorted by fear.\n\nDestroy his masks and we will walk unharmed through dis passage.", progress = "His arrogance blinds him. He will soon learn de error of his ways.", completion = "As I said, his truth is distorted by fear.", objectives = "Destroy Vol'jamba's masks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49493] = { id = 49493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul's Ethical Dilemma", description = "Hm.\n\nDe Gurubashi have earned a reputation for betrayal and weakness. Their activities in Zul'Gurub will be a stain on our records for generations to come.\n\nOn de other hand...\n\nDe Zandalari are above de use of slaves. We are strong, capable. De very existence of mindslaves in dis great city is insulting.\n\nDere is a chant dat will free their minds. Use it near de mindslaves to free dem. \n\nOr you can simply kill dem. It makes no difference to me.", completion = "Weakness or pride... I think often on de Zandalari's priorities.", objectives = "Free 9 Mindslaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49494] = { id = 49494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuvembi Brew", description = "Zuvembi brew is arguably a witch doctor's most insidious concoction.\n\nDriven by de cauldron master's strength of mind, Zuvembi brew takes de will of those who breathe its fumes. It makes dem compliant, easily manipulated.\n\nIt is low magic, relying upon ancient cantrips and recipes known only to witch doctors of a certain skill. If we want to eradicate dis brew, we must slay those dat brew it.\n\nFind de Zuvembi brewer lurking here and see dat dis knowledge is erased.", progress = "Dis primitive magic cannot be allowed to proliferate.", completion = "Good. Dis thread has been severed.", objectives = "Slay Zuvembi Brewer Zekal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49495] = { id = 49495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enforcing Fate", description = "Vol'jamba is busy consolidating his power. His Sight has shown him dat he will fight, and perhaps even dat he will die, and so he looks to all his tools to save himself.\n\nI will need you to be my hands, as he will come as soon as I show myself. You will undo all de preparations he has made for dis day.\n\nDo as I say and we will both find ourselves enjoying de king's favor.", progress = "His vision is imperfect. We will use dis to end him.", completion = "<Zul rubs his hands together.>\n\nGood. Now we are ready to draw him out.", objectives = "Sabotage Vol'jamba's precautions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49522] = { id = 49522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carentan's Payment", description = "Well done, my friend. Well done, indeed.\n\nYou see that dusty crate in the corner of the room? You'll find it contains the ancient scroll and a generous purse of gold, as we agreed.\n\nPlease, take your reward. You've certainly earned it.", objectives = "Open the Dusty Crate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49523] = { id = 49523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bad Deal", description = "<Carentan escaped!\n\nRoko, the tortollan merchant who set up this deal in the first place, will want to know what happened.\n\nWhen you last spoke, Roko said he would be heading to Boralus.>", completion = "Hmm. A scam, was it? You have my apologies for putting you in harm's way.\n\nThis man should be delivered to justice. He may be in hiding now, but I am very, very patient.", objectives = "Speak with Roko in Tradewinds Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49529] = { id = 49529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spring Cleaning" }
quests[49531] = { id = 49531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beauty of Marketing", description = "While us Fizzbrackets may not be goblins, we still know a business opportunity when we see one! The resort staff is getting trained, the place is getting cleaned up, now all we need is some quality marketing!\n\n<Wulferd holds up a familiar looking box.>\n\nBehold! The wondrous Gnomish engineering feat that is the S.E.L.F.I.E. Camera! Now, if only there was a generous {race} willing to capture the radiance of this place.\n\nMake sure you look like you're enjoying yourself out there!", progress = "If your smile isn't at least half of the picture, I don't want to see it!", completion = "These are perfect, you look dashing! Now I need to figure out how to get these out to our target customers.", objectives = "Take S.E.L.F.I.E.s with the resort's sights and wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49532] = { id = 49532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Shadowmoon Valley!", description = "All able-bodied members of the Horde are hereby ordered to report to Blood Guard Gulmok at Shadowmoon Valley in Outland.\n\nThe Burning Legion is attempting to lay siege to Shadowmoon Village, but our elite Kor'kron force is showing them what it means to fight against the Horde.\n\nCrush the Legion.\n\nFor the Horde!", completion = "Welcome to the battlefield, grunt!", objectives = "Speak to Blood Guard Gulmok at Shadowmoon Valley in Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49533] = { id = 49533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Howling Fjord!", description = "All able-bodied members of the Horde are hereby ordered to report to Apothecary Lysander in Howling Fjord.\n\nThe Forsaken have established a stronghold on the eastern shores of Northrend.\n\nNow is the time to strike at the Scourge with our military might and a new plague that is being developed by the Royal Apothecary Society.\n\nFor the Horde!", completion = "Ah, {name}, you have arrived!\n\nLet's get to work.", objectives = "Speak to Apothecary Lysander in Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49534] = { id = 49534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Zul'Drak!", description = "All able-bodied members of the Horde are hereby ordered to report to Crusader Lord Lantinga in Zul'Drak.\n\nThe Scourge is massacring the local population in Zul'Drak and converting them over to be part of the Scourge army.\n\nAssist the Argent Crusade and the Ebon Blade in stopping this threat.\n\nFor the Horde!", completion = "Death and acts of sacrilege pervert this land.\n\n<Lantinga lets out a drawn-out sigh.>\n\nThankfully, we're here to stop it.", objectives = "Speak with Crusader Lord Lantinga in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49535] = { id = 49535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Sholazar Basin!", description = "All able-bodied members of the Horde are hereby ordered to report to Archmage Pentarus in Dalaran over Crystalsong Forest.\n\nHemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin, but has gone missing.\n\nWe do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King.\n\nFor the Horde!", completion = "I am glad you're here, {race}. Hemet has not been heard from for quite some time, and I could really use your help finding him.", objectives = "Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49536] = { id = 49536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Storm Peaks!", description = "All able-bodied members of the Horde are hereby ordered to report to Rin Duoctane in Dalaran over Crystalsong Forest.\n\nThe goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers.\n\nSpeak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King.\n\nFor the Horde!", completion = "Yo! Do I have an explosive proposition for you, pal....", objectives = "Speak with Rin Duoctane in Dalaran over Crystalsong Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49537] = { id = 49537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Icecrown!", description = "All able-bodied members of the Horde are hereby ordered to report to Sky-Reaver Klum in Dalaran over Crystalsong Forest.\n\nThe Warsong Offensive needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself.\n\nIt is time to make the Lich King pay for his crimes.\n\nFor the Horde!", completion = "The Warsong Offensive is ready to strike at the heart of the Scourge, {class}. Are you up to the challenge?", objectives = "Speak to Sky-Reaver Klum in Dalaran over Crystalsong Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49538] = { id = 49538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Jade Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to General Nazgrim in Orgrimmar.\n\nRecent victories in our naval battles against the Alliance strengthens our resolve.\n\nReport to Grommash Hold and assist the Horde's invasion fleet.\n\nFor the Horde!", completion = "Lok'tar ogar, {name}. You've arrived not a moment too soon....", objectives = "Report to General Nazgrim in Grommash Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49539] = { id = 49539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Valley of the Four Winds!", description = "All able-bodied members of the Horde are hereby ordered to report to Chen Stormstout in the Valley of the Four Winds.\n\nThe adventuring spirit of the Stormstouts is something that the Horde can learn from.\n\nTravel with the Stormstouts and discover what secrets Pandaria holds.\n\nFor the Horde!", completion = "You seem like someone who needs some excitement in their life. Excitement... and beer!", objectives = "Speak with Chen Stormstout in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49540] = { id = 49540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Krasarang Wilds!", description = "All able-bodied members of the Horde are hereby ordered to report to Zhu's Watch in Krasarang Wilds.\n\nThere have been rumors that the pandaren living in Krasarang Wilds are not their usual self.\n\nSpeak with Ken-Ken at Zhu's Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.", completion = "What the dook is going on here, {race}?!\n\nWhy are pandaren so sad?!", objectives = "Speak with Ken-Ken in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49541] = { id = 49541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Kun-Lai Summit!", description = "All able-bodied members of the Horde are hereby ordered to assist Lorewalker Cho in Kun-Lai Summit.\n\nSpeak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit.\n\nFor the Horde!", completion = "Traveling to Kun-Lai? Right this way, wanderer, right this way!", objectives = "Speak to the Messenger Grummle in Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49542] = { id = 49542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Townlong Steppes!", description = "All able-bodied members of the Horde are hereby ordered to report to Taran Zhu in Townlong Steppes.\n\nThe Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so.\n\nAssist them with their assault against the yaungol.\n\nFor the Horde!", completion = "Welcome to Townlong Steppes, outsider.\n\nIf you insist on wandering in to the darkest places of Pandaria then far be it from me to not put you to good use.", objectives = "Speak with Taran Zhu in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49543] = { id = 49543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Dread Wastes!", description = "All able-bodied members of the Horde are hereby ordered to report to Bowmistress Li on the Serpent's Spine in the Vale of Eternal Blossoms.\n\nThe Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria.\n\nYou can reach Bowmistress Li by securing a kite and flying to the Serpent's Spine.\n\nDestiny calls!", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49545] = { id = 49545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Frostfire Ridge!", description = "All able-bodied members of the Horde are hereby ordered to report to Farseer Drek'Thar in Frostfire Ridge.\n\nThe destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them.\n\nWith Farseer Drek'Thar's aid, we will be able to establish a strategic position in Draenor to fight against our enemies.\n\nFor the Horde!", completion = "I am glad to see you are well after Tanaan Jungle.\n\nWe have much to do.", objectives = "Speak to Farseer Drek'Thar in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49546] = { id = 49546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Gorgrond!", description = "All able-bodied members of the Horde are hereby ordered to report to Durotan in Gorgrond.\n\nDurotan is seeking allies to help us navigate the savage landscape of Gorgrond in hopes that we will find ancient powers to help us destroy the Iron Horde.\n\nSpeak with him and see what secrets the lands hold.\n\nFor the Horde!", completion = "Gorgrond is no place for armies. We are now stepping into the domain of legends.", objectives = "Speak to Durotan in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49547] = { id = 49547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Talador!", description = "All able-bodied members of the Horde are hereby ordered to report to Foreman Grobash in Talador.\n\nThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.\n\nForeman Grobash is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.\n\nFor the Horde!", completion = "It is good to see you, Commander {name}. I require your advisement.", objectives = "Speak with Foreman Grobash in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49548] = { id = 49548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Spires of Arak!", description = "All able-bodied members of the Horde are hereby ordered to report to Azik in Spires of Arak.\n\nThere have been wingless arakkoa seen fleeing from Spires of Arak. Rumors suggest that they are running from an Iron Horde superweapon.\n\nWe need to find out what is causing them to leave their homeland, and why their wings have withered.\n\nFor the Horde!", completion = "<Azik looks you up and down.>\n\nAzik is betting you are someone of importance to your people.\n\nCome closer, friend. Azik could use your help.", objectives = "Speak with Azik in the Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49549] = { id = 49549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Nagrand!", description = "All able-bodied members of the Horde are hereby ordered to report to Stone Guard Brox in Nagrand on Draenor.\n\nThrall is establishing a Horde outpost and needs help to stop the Warsong clan.\n\nSpeak with Bron Skyhorn to fly to Nagrand and meet up with the supply caravan.\n\nFor the Horde!", completion = "They came at us... from... nowhere.\n\n<The stone guard nearly passes out.>", objectives = "Speak to Stone Guard Brox in Nagrand on Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49550] = { id = 49550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Shadowmoon Valley!", description = "All able-bodied citizens of the Alliance are to report to Wing Commander Nuainn in Shadowmoon Valley on Outland.\n\nThe Burning Legion are laying siege to Wildhammer Stronghold, endagering our people and threatening their lives.\n\nWe need to reinforce the stronghold and stop the Burning Legion's relentless assault!\n\nGlory to the Alliance!", completion = "We're gettin' hammered out here, lad.\n\nI hope you're here to help.", objectives = "Speak with Wing Commander Nuainn in Shadowmoon Valley on Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49551] = { id = 49551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Howling Fjord!", description = "All able-bodied citizens of the Alliance are to report to Macalroy in Howling Fjord.\n\nThe port town of Valgarde is located in the heart of the Howling Fjord, and it allows for the Alliance to have an advantageous position to strike at the Scourge.\n\nAssist the soldiers stationed there.\n\nGlory to the Alliance!", completion = "What is it?!\n\nCan't you see I'm already busy trying to get this port ready, {race}?", objectives = "Speak with Macalroy in Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49552] = { id = 49552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Zul'Drak!", description = "All able-bodied citizens of the Alliance are to report to Crusader Lord Lantinga in Zul'Drak.\n\nThe Scourge is massacring the local population in Zul'Drak and converting them over to be part of the Scourge army.\n\nAssist the Argent Crusade and the Ebon Blade in stopping this threat.\n\nGlory to the Alliance!", completion = "Death and acts of sacrilege pervert this land.\n\n<Lantinga lets out a drawn-out sigh.>\n\nThankfully, we're here to stop it.", objectives = "Speak with Crusader Lord Lantinga in Zul'Drak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49553] = { id = 49553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Sholazar Basin!", description = "All able-bodied citizens of the Alliance are to report to Archmage Pentarus in Dalaran over Crystalsong Forest.\n\nHemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin, but has gone missing.\n\nWe do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King.\n\nGlory to the Alliance!", completion = "I am glad you're here, {race}. Hemet has not been heard from for quite some time, and I could really use your help finding him.", objectives = "Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49554] = { id = 49554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Storm Peaks!", description = "All able-bodied citizens of the Alliance are to report to Rin Duoctane in Dalaran over Crystalsong Forest.\n\nThe goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers.\n\nSpeak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King.\n\nGlory to the Alliance!", completion = "Yo! Do I have an explosive proposition for you, pal....", objectives = "Speak with Rin Duoctane in Dalaran over Crystalsong Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49555] = { id = 49555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Icecrown!", description = "All able-bodied citizens of the Alliance are to report to Officer Van Rossem in Dalaran over Crystalsong Forest.\n\nThe Valiance Expedition needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself.\n\nIt is time to make the Lich King pay for his crimes.\n\nGlory to the Alliance!", completion = "The Valiance Expedition is ready to strike at the heart of the Scourge, {class}. Are you up to the challenge?", objectives = "Speak with Officer Van Rossem in Dalaran over Crystalsong Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49556] = { id = 49556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Jade Forest!", description = "All able-bodied citizens of the Alliance are to report to Stormwind Keep in Stormwind.\n\nGrand Admiral Jes-Tereth is assembling a team for a high priority mission.\n\nHead to Stormwind Keep immediately to be briefed.\n\nGlory to the Alliance!", completion = "Our role is of utmost importance, {name}.\n\nAdmiral Taylor and his flagship have gone missing.... More importantly, the young Prince was with him, and it is our primary objective to bring him back home safely.", objectives = "Report to Grand Admiral Jes-Tereth in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49557] = { id = 49557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Valley of the Four Winds!", description = "All able-bodied citizens of the Alliance are to report to Chen Stormstout in the Valley of the Four Winds.\n\nThe adventuring spirit of the Stormstouts is something that the Alliance can learn from.\n\nTravel with the Stormstouts and discover what secrets Pandaria holds.\n\nGlory to the Alliance!", completion = "You seem like someone who needs some excitement in their life. Excitement... and beer!", objectives = "Speak with Chen Stormstout in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49558] = { id = 49558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Krasarang Wilds!", description = "All able-bodied citizens of the Alliance are to report to Zhu's Watch in Krasarang Wilds.\n\nThere have been rumors that the pandaren living in Krasarang Wilds are not their usual self.\n\nSpeak with Ken-Ken at Zhu's Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.", completion = "What the dook is going on here, {race}?!\n\nWhy are pandaren so sad?!", objectives = "Speak with Ken-Ken in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49559] = { id = 49559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Kun-Lai Summit!", description = "All able-bodied citizens of the Alliance are to assist Lorewalker Cho in Kun-Lai Summit.\n\nSpeak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit.\n\nGlory to the Alliance!", completion = "Traveling to Kun-Lai? Right this way, wanderer, right this way!", objectives = "Speak to the Messenger Grummle in Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49560] = { id = 49560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Townlong Steppes!", description = "All able-bodied citizens of the Alliance are to report to Taran Zhu in Townlong Steppes.\n\nThe Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so.\n\nAssist them with their assault against the yaungol.\n\nGlory to the Alliance!", completion = "Welcome to Townlong Steppes, outsider.\n\nIf you insist on wandering in to the darkest places of Pandaria then far be it from me to not put you to good use.", objectives = "Speak with Taran Zhu in Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49561] = { id = 49561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Dread Wastes!", description = "All able-bodied citizens of the Alliance are to report to Bowmistress Li on the Serpent's Spine in the Vale of Eternal Blossoms.\n\nThe Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria.\n\nYou can reach Bowmistress Li by securing a kite and flying to the Serpent's Spine.\n\nGlory to the Alliance!", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49562] = { id = 49562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Shadowmoon Valley!", description = "All able-bodied citizens of the Alliance are to report to Prophet Velen in Shadowmoon Valley on Draenor.\n\nThe destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them.\n\nWith Prophet Velen's blessing, we will be able to establish a strategic position in Draenor to fight against the enemies of Azeroth.\n\nGlory to the Alliance!", completion = "<Prophet Velen welcomes you with a curious look, then a warm nod.>\n\nSo it begins....", objectives = "Speak with Prophet Velen in Shadowmoon Valley on Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49564] = { id = 49564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Gorgrond!", description = "All able-bodied citizens of the Alliance are to report to Yrel in Gorgrond.\n\nYrel and Maraad are requesting for a small expedition to be sent into the wilds of Gorgrond.\n\nWe hope to gain a better understanding of the land in hopes that it will show us how to exploit weaknesses in the Iron Horde.\n\nAssist them with their expedition.\n\nGlory to the Alliance!", completion = "Welcome to Gorgrond, commander.\n\nWe have just arrived ourselves.", objectives = "Speak with Yrel in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49565] = { id = 49565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Talador!", description = "All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador.\n\nThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.\n\nForeman Eksos is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.\n\nGlory to the Alliance!", completion = "It is good to see you, Commander {name}. I require your advisement.", objectives = "Speak with Foreman Eksos in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49566] = { id = 49566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Spires of Arak!", description = "All able-bodied citizens of the Alliance are to report to Azik in Spires of Arak.\n\nThere have been wingless arakkoa seen fleeing from Spires of Arak. Rumors suggest that they are running from an Iron Horde superweapon.\n\nWe need to find out what is causing them to leave their homeland, and why their wings have withered.\n\nGlory to the Alliance!", completion = "<Azik looks you up and down.>\n\nAzik is betting you are someone of importance to your people.\n\nCome closer, friend. Azik could use your help.", objectives = "Speak with Azik in the Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49567] = { id = 49567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Nagrand!", description = "All able-bodied citizens of the Alliance are to report to Lieutenant Balfor in Nagrand on Draenor.\n\nYrel is recommending that the Alliance establish an outpost in Nagrand to help in our fight against the Warsong clan.\n\nSecure a flight to Nagrand and meet up with Lieutenant Balfor and the supply caravan.\n\nGlory to the Alliance!", completion = "They came at us... from... nowhere.\n\n<The lieutenant nearly passes out.>", objectives = "Speak with Lieutenant Balfor in Nagrand on Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49569] = { id = 49569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down by the Riverside", description = "We have de aid of Krag'wa and de Gob Squad. We must get back to Zul'jan and begin our plan to stop de blood trolls.\n\nWe have one problem. De Gob Squad are unable to move their mech fast enough in de jungle. We must take it by boat.\n\nDe two of us will ride with dem and ensure de blood trolls do not destroy de mech.\n\nI will run ahead and get de boat ready near de riverbank. Meet us dere.", completion = "We made it, {name}. Now comes de hard part. Are you ready?", objectives = "Sail down the river with Talanji and defend the Gob Squad's A.M.O.D.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49570] = { id = 49570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rocky Start", description = "<As you thumb through the book, the pages are unusually thick and embedded on their surface are runic-shaped jewels. Samuel Colton notices you looking and approaches.>\n\nAh, now that's a treasure I've had for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at the thought of something being transcribed in jewels.\n\nCome to think of it, I wonder if Zooey Inksprocket would be able to decipher it. Say, {name}, would you mind taking it over to her and see if she can translate it?", completion = "Y-yes? Can I help you?\n\n<You hand the book over to Zooey and ask for it to be translated. As she turns each page, wondrous expressions cross the scribe's face.>\n\nOh my, I've only ever heard of such books in existence but have never seen one up close. Do you know what this is?\n\nIt's ancient earthen. And this book must be centuries old!\n\nOf course I'll help translate it! Only... well... my ancient earthen isn't so great. I'll need some reference materials.", objectives = "Bring the book to Zooey Inksprocket and see if she can translate the text.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49571] = { id = 49571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Through the Past", description = "Let's see, Jane Hudson probably still has her book on ancient runes and carvings. And I believe Tal'ana has a few scrolls he picked up from Ulduar.\n\nOH! And Toopa found what appeared to be some type of codex the last time he ventured out. I remember seeing the runes on it and they bear a striking resemblance to the ones in this book.\n\nIf you could convince them to uh... lend us those items for a bit, I believe I just might be able to create a translation for you. I won't even charge you for it!", progress = "How goes the translation?", completion = "Was she able to translate it?\n\n<You hand the book over to Samuel and he begins to read it.>\n\nThis is incredible. This earthen was able to create jewels with light at special shrines he built. I mean, he mentions building several of them all over the world but...\n\n<Samuel pulls out a few maps and begins scanning them.>", objectives = "Ask Jane Hudson for her book of Primordial Races: Runes and Writings. Ask Tal'ana for his Scrolls of the Stonefather. And ask Toopa for the The Dungard Codex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49572] = { id = 49572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of the Sea", description = "This next shrine is right here, in Tiragarde Sound.\n\nAccording to the journal, the earthen mentions creating bluish hued jewels. I wonder if that's anything like the kyanite we have here.\n\nGo and see if the shrine still stands. Hopefully it's still in a usable state.\n\nI'll continue to study the journal for more information.", completion = "<As you peer at the shrine in front of you, you can't help but revel at the construction of it.\n\nSeamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point.>", objectives = "Investigate the Shrine of the Sea in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49573] = { id = 49573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of the Eventide", description = "There are two more shrines here on Kul Tiras.\n\nI believe this next one resides within Drustvar, near the Bleak Hills Mine, southeast of Corlain.\n\nHere are the notes on that shrine. Should it also need mending, I'm positive your skills with jewels can meet the challenge of repairing it.", completion = "<Inspecting the shrine, you realize that several of the gems embedded on its surface are cracked and need to be replaced.>", objectives = "Travel to the location marked on your map and investigate the shrine in Drustvar. Do what you can to repair the shrine, should the need arise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49574] = { id = 49574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of Storms", description = "Yes, I believe there are a few here in Kul Tiras. You should visit them, {name}, investigate them. See if what this book says is true.\n\nThis particular shrine he mentions sounds like it may reside near Brennadam, in Stormsong Valley.\n\nIt should be fairly easy to find. If my calculations are correct, it should be just north of that town.\n\nHere are the notes on that one. And I've marked its location for you on your map. Good luck, {name}.", completion = "<Upon your investigation you discover that the shrine has a couple locations where jewels appeared to have been located, but no longer exist.\n\nAdditionally, the center jewel appears to have several cracks in it as well.>", objectives = "Travel to the location marked on your map and investigate the shrine in Stormsong Valley. Do what you can to repair the shrine, should the need arise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49575] = { id = 49575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Jewel of the Tides", description = "<An absence you assume to be a mistake, you quickly survey the area for something that might fit there yet you find nothing.\n\nHowever, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>", progress = "<Perhaps finding the missing centerpiece will give you a clue into the shrine's operation?>", completion = "<As you affix the gem back into the center of the shrine, a strange pulse emanates from it.\n\nThe shrine, now whole again, begins to hum with energy.>", objectives = "Speak with \"Slippery\" Salton and learn what you can about the missing centerpiece.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49576] = { id = 49576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Prospects", description = "<Checking your notes, you find that the earthen had extracted the gems from some earth elementals to the south.\n\nLooking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead.\n\nPerhaps investigating there will yield some clues as to where to find these jewels.>", progress = "<All of the cracked jewels will definitely need to be replaced.>", completion = "<You begin to remove all the cracked gems from the shrine and carefully start placing the new ones in.\n\nPlacing the final one, a pulse radiates from the shrine, as the light in the area seems to draw into it.\n\nThat strange, similar glow now emanating from the shrine leads you to believe it is once again active.>", objectives = "Investigate Gol Osigr for clues about the jewels that were used to construct the shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49577] = { id = 49577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking the Surface", description = "<Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest.\n\nPerhaps you can prospect the earth in that area to find more of those jewels and repair the shrine.>", progress = "<The placement of the jewels on this shrine appear to be placed in a rather intricate fashion.>", completion = "<Using your tools, you carefully shape the jewels and affix them into the empty slots on the shrine.\n\nUsing the remainder, you are able to fill in the cracks of the center jewel, giving it a flush surface.\n\nAs you place the final jewel, a similar pulse of energy radiates from the shrine as the light in the area seems to draw into it. A strange glow now emanating from the shrine leads you to believe it is once again active.>", objectives = "Go to the Windshorn Hills and gather 20 Shard of Golden Beryl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49578] = { id = 49578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "I've been to Zandalar before. Crazy place, full of dinosaurs and other unspeakable beasts. However one of the shrine's locations the journal speaks of sounds like a place they call Vol'dun.\n\nIt's a foreboding desert, full of canyons, with a great pyramid in the center.\n\nIf my calculations are correct though, the shrine ought to be around this area. I'll mark it for you on your map.\n\nAnd let's hope it's still in one piece.", sourceObjective = "Travel to the location marked on your map and investigate the shrine in Vol'dun. Do what you can to repair the shrine, should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[49579] = { id = 49579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "This next shrine might be a bit difficult to get to. It resides in Zandalar, the heart of the troll empire.\n\nWell, maybe not the main city itself, but close to it. Actually...\n\n<Samuel checks a map he has laid out.>\n\nAh, it's not too far from (POI). I've heard there's been some strife there between the Horde and Alliance. Perhaps there's a camp there you can work out of.\n\nHere are you notes for the shrine and the location for it should be marked on your map.", sourceObjective = "Travel to the location marked on your map and investigate the shrine in Zandalar. Do what you can to repair the shrine, should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[49580] = { id = 49580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "The last shrine resides in Nazmir, a swamp infested with deadly creatures and home of the blood trolls.\n\nLuckily an ally of mine gave me a rather detailed map of that region and if my calculations are correct...\n\n<Samuel looks quickly back and forth between the journal and his map and finally stops his finger on the map.>\n\nIt should be right there. Take note of its location and here are the notes for that shrine. Good luck, {name}.", sourceObjective = "Travel to the location marked on your map and investigate the shrine in Nazmir. Do what you can to repair the shrine, should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[49581] = { id = 49581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sun-Speckled Dunes", description = "<Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nChecking your notes, it appears that these dunes were located south of your current location.>", progress = "<These gems have a very strong structure. Time, in addition to the winds, must have also taken its toll on them.>", completion = "<You carefully remove the old, weathered gems from the shrine and replace your polished gems in their place.\n\nAs you place the final gem, a similar pulse of energy radiates from the shrine as the light in the area seems to draw into it. A strange glow now emanating from the shrine leads you to believe it is once again active.>", objectives = "Go to the location on your map where you believe these gems to be and recover 8 of them. Polish and shape them when you've collected enough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49582] = { id = 49582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Not All That Glitters...", description = "<You reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\".\n\nGiven your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>", progress = "<When you're done replacing the central gem, you think you might still be able to sell the old one.>", completion = "<Returning to the shrine, you begin to pluck the old gem from its holding place. As you do, the gem cracks again and shatters in your hands.\n\nApparently these gems are much more fragile than you originally thought.\n\nVery carefully, you replace the gem you obtained into the slot.\n\nOnce affixed, the familiar pulse radiates once more from the shrine and the glow emanating from it confirms its restoration.>", objectives = "Travel to Atal'Dazar and find a replacement for the broken jewel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49583] = { id = 49583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out With the Old", description = "<It's clear though that time has had its way with these gems, some eroded and chipped in places.\n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>", progress = "<Interesting that the cut should be so similar, you wonder how the design has persisted all these years.>", completion = "<Replacing each gem, they fit perfectly into the slots confirming your suspicions of their similarities.\n\nAs you place the final gem, a peaceful glow now emanating from the shrine leads you to believe it is once again active.>", objectives = "Cut 4 Natant Rubellites and replace the old ones with the new.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49584] = { id = 49584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Chapter", description = "<Samuel puts down the journal and looks back up at you.>\n\nWhile trying to figure out where the shrines reside, I came across an entry that mentioned him exploring an area that sounds very similar to Dustwallow Marsh.\n\nHe mentions hiding something of great importance there.\n\nIt's a long shot, given when this earthen roamed Azeroth, but perhaps if you were to retrace his final steps you may find something.\n\nI'll mark the location on your map.", progress = "Who knows what you may find out there. Hopefully something...", completion = "What did you find?\n\n<You hand the final chapter and its transcription over to Samuel. As he reads through it, he reaches the page with the design for the lens and his eyes go wide.>\n\nYou've found it, {name}! We can construct a lens now and use it with the shrines.\n\nAlthough, the reagents for this design are quite... rare. But nevertheless you've done it!\n\nIt was an honor to work with you on this, {name}.", objectives = "Travel to the location marked on your map and see what you can find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49585] = { id = 49585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rocky Start", description = "<As you thumb through the book, you see odd-looking runes carved out of jewels embedded in the stone pages. Seshuli notices you looking and approaches you.>\n\nAh, dat's been a treasure of mine for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at de thought of something being written in jewels.\n\nCome to think of it, I wonder if Grazzul would know what it says. {name}, would you mind taking it over to him and see if he can translate it?", completion = "What do you need?\n\n<You hand the book over to Grazzul and ask for it to be translated. As he turns each page, wondrous expressions cross the scribe's face.>\n\nI've only heard of such books in existence but I've never seen one before. Do you know what dis is?\n\nDis is ancient earthen. And dis book is centuries old!\n\nOf course I'll help to translate it, only... well... my ancient earthen isn't so great. I'll need some things to do dis.", objectives = "Bring the book to Grazzul and see if he can translate the text.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49586] = { id = 49586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Through the Past", description = "Let's see, Examiner Alerinda has a book on ancient runes and carvings. I think Koatini has a few scrolls he brought with him from Ulduar.\n\nOH! And Chronicler Shoopa found a codex de last time he ventured out. I remember seeing de runes on it and dey look a lot like de ones in dis book.\n\nMaybe you can convince dem to lend us dose books for a bit, and I think I can create a translation for you.", progress = "How is de translation going?", completion = "Was he able to translate it? \n\n<You hand the book over to Seshuli and she begins to read it.>\n\nDis is incredible. Dis earthen was able to create jewels with de light. And dose shrines he's built, I mean, he mentions building several of dem but...\n\n<Seshuli pulls out a few maps and begins scaninng them.>", objectives = "Ask Examiner Alerinda for her book of Primordial Races: Runes and Writings. Ask Koatini for his Scrolls of the Stonefather. And ask Chronicler Shoopa for the The Dungard Codex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49587] = { id = 49587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of Nature", description = "Another shrine resides right here in Zuldazar.\n\nAccording to de journal, de earthen talks about creating green hued jewels dere. I wonder if dat's anything like de viridium we find in de ore we mine.\n\nGo and see if de shrine still stands. Hopefully, we can still make use of it.\n\nI'll continue to study de journal for more information.", completion = "<As you observe the shrine, it's quite clear that the central jewel is badly broken and in need of replacement.>", objectives = "Investigate the Shrine of Nature in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49588] = { id = 49588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of the Sands", description = "Dere are two more shrines here on Zandalar. Dis next one resides within Vol'dun, near Bonetrail Gulch.\n\nHopefully de Faithless haven't defiled de shrine.\n\nHere are de notes on dat location. Should dat shrine also need fixing, I think your skills with jewels will probably be enough to fix it.", completion = "<Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some.>", objectives = "Travel to the location marked on your map and investigate the shrine in Vol'dun. Do what you can to repair the shrine, should the need arise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49589] = { id = 49589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of the Dawning", description = "Yea, I believe there are a few here on Zandalar. You should find dem, {name}, investigate dem. See if what dis book says is true.\n\nDis particular shrine sounds like it might be in Nazmir. If my calculations are correct, it should be just south of Torga's Rest.\n\nDat loa was a mighty one. It is truly sad dat it is no longer with us.\n\nHere are de notes on dat one. And I've marked its location for you on your map. Loa be with you, {name}.", completion = "<Upon inspection of the shrine, you notice something... familiar.\n\nThe cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.>", objectives = "Travel to the location marked on your map and investigate the shrine in Nazmir. Do what you can to repair the shrine, should the need arise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49590] = { id = 49590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "As you peer from one gem to the next, you realize that the shrine appears to be fine, yet no power radiates from it.\n\nPulling out your jewelcrafting tools, you begin to inspect the central gem and realize that there is in fact a flaw. A small crack near the base of it that permeates through the gem towards the back.\n\nYou reference your notes on the shrine and discover that this gem came from a \"golden sanctuary\".\n\nPerhaps someone back at the Explorer's League Campsite will know what this means.", sourceObjective = "Travel to the Reliquary Camp and ask around about the \"golden sanctuary\". Then find a replacement gem once you learn of its location.", sourceObjectiveStatus = "unverified-source-field" }
quests[49591] = { id = 49591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some.\n\nLooking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nSamuel added his own note saying he believes the location of these gems to be south of the shrine's location." }
quests[49592] = { id = 49592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.\n\nIt's clear though that time has had its way with these gems, some eroded and chipped in places. \n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut." }
quests[49593] = { id = 49593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "I once viisted Kul Tiras. Da humans dere not be too friendly to us Zandalari. However one of da shrines be dere, in Tiragarde Sound.\n\nDat place have da most humans of all dat land. Ya need to be watchin' your back out dere, {name}.\n\nI'll mark da location of it on your map for ya.\n\nAnd let's be hoping dem humans didn't mess wit it.", sourceObjective = "Travel to the location marked on your map and investigate the shrine in Tirigarde Sound. Do what you can to repair the shrine, should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[49594] = { id = 49594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Da next shrine be a in a place dey call Drustvar. From what I be hearin', dat place is full of witches.\n\nDey use deir magics to bring tings ta life. But lookin at da map and where I tink dis shrine be, ya may not be needing to run into any of dem.\n\nIt's pretty close ta da Smuggler's Cove. I'd make ya way dere and den find da shrine. I'll mark ya map for ya where I tink it is.", sourceObjective = "Travel to the location marked on your map and investigate the shrine in Drustvar. Do what you can to repair the shrine, should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[49595] = { id = 49595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Da last shrine in Kul Tiras be in a green place dey call Stormsong Valley. Da humans dere probably won't be givin' ya too much trouble.\n\nBut da shrine be pretty dead center in da land, so ya probably gonna have ta do some travelin'. I'll mark it on ya map for ya.", sourceObjective = "Travel to the location marked on your map and investigate the shrine in Stormsong Valley. Do what you can to repair the shrine, should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[49596] = { id = 49596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "As you peer at the rock altar in front of you, you can't help but revel at the construction of it. Seamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing.\n\nHowever, someone who had not been there before has shown up. Perhaps he might know the whereabouts of the shrine's missing piece.", sourceObjective = "Speak with \"Slippery Salton\" and learn what you can about the missing centerpiece.", sourceObjectiveStatus = "unverified-source-field" }
quests[49597] = { id = 49597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME" }
quests[49598] = { id = 49598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Upon your investigation you discover that the shrine has several locations where jewels appeared to have been located, but no longer exist. Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the north.\n\nPerhaps you can prospect the earth in that area to find more of those jewels." }
quests[49599] = { id = 49599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Chapter", description = "<Seshuli puts down the journal and looks back up at you.>\n\nWhile trying to figure out where de shrines reside, I came across an entry dat mentioned him exploring an area dat sounds very similar to Dustwallow Marsh.\n\nIt could be a long shot, given when dis earthen roamed Azeroth, but maybe if you retrace his final steps, you may find something.\n\nI'll mark his last location for you on your map.", progress = "Who knows what you'll find out dere. Hopefully something...", completion = "Did you find anything?\n\n<You hand the final chapter and its transcription over to Seshuli. As she reads through it, she reaches the page with the design for the lens and her eyes go wide.>\n\nYou found it, {name}! We can make a lens now and use it with de shrines.\n\nAlthough, de reagents for dis design are quite... rare. Still, you've done it!\n\nIt was an honor to work with you on dis, {name}.", objectives = "Travel to the location marked on your map and see what you can find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49613] = { id = 49613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermoon City", description = "The nightborne have been isolated from the world for thousands of years. Now that they have reemerged, it is up to us to guide them along the right path.\n\nRegent Lord Theron has extended an invitation to the nightborne to meet with us in Silvermoon.\n\nCome, {name}, let us travel to Silvermoon with Thalyssra.", completion = "Good, we're all here. Our guests should be arriving shortly.", objectives = "Meet with Lady Liadrin in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49614] = { id = 49614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightborne", description = "The Warchief will be pleased with our success.\n\nThalyssra and her nightborne will prove strong allies, I am sure.", completion = "You return with good news, {name}.", objectives = "Return to Ji Firepaw in Orgrimmar to hear the end of this tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49615] = { id = 49615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trust of a King", description = "Well, now dat you are settled in, you had best go speak with my father. You can find him up upon de throne, his advisors close at hand, pouring poison in his ear, no doubt.\n\nDe lift behind you can take you to de Golden Throne above us.", completion = "Very prompt. Now, I have need of your hands.", objectives = "Speak with King Rastakhan at the Golden Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49661] = { id = 49661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locally Sourced Eggs", description = "There is nothing in the world greater than food made from the best, freshest ingredients!\n\nMy good friend I am on a hunt. A hunt for the perfect eggs! I have heard tale of eel eggs. A delicate texture, a slight undersea saltiness... such a unique flavor profile! I must have them!\n\nThe eels here lay their eggs on the land before returning to the sea. Please, gather these eggs for me so that I may create only the most elegant of omelets!", objectives = "Collect 10 Coilscale Eggs from Coilscale Nests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49662] = { id = 49662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Key", description = "Korthek has grown spiteful and arrogant over the years, but I realize now that he has grown mad as well.\n\nMythrax will kill all of us if he is released.\n\nFor too long, I've held out hope that I could convince Korthek peacefully to abandon his heresy. I was wrong.\n\nAll of Zandalar is at risk while Korthek and his allies hold even one key to Mythrax's prison.\n\nMeet me outside his fortress in the north. We will confront my old friend \"Emperor\" Korthek and end this together.", completion = "We are surrounded by Faithless out here, {name}. We must move quickly.", objectives = "Meet Vorrik at Bwoljin's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49663] = { id = 49663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "False Prophecies", description = "Now dat dis nuisance is out of de way, I can return my focus to de city. Zuldazar has languished while I was away.\n\nYou should return to Rastakhan. Let de king know dat his will has been carried out and dat dis false prophet is no more.\n\nYou might think to share Vol'jamba's prophecy with him, if you feel it worth his notice. I cannot say it will change anything at all.", completion = "Perhaps Zul will remember his place going forward.", objectives = "Return to King Rastakhan at Dazar'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49664] = { id = 49664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Anarchy", description = "Even after all these years, I can feel the ancient power of Sethraliss in this place. My loa endures.\n\nOur task ahead is great and I will need a clear, focused mind to accomplish it. Allow me a few moments to meditate here, like I did in ages past.\n\nIn the meantime, you should help the vulpera stir up trouble however you can. They seem to know you, and a large enough disturbance will distract the Faithless from our mission.\n\nMeet me back here when you're done and we'll proceed together.", completion = "{name}?! We gotta stop meeting in places like this.\n\nActually, let's ALWAYS meet in places like this!\n\nYou up for killing some Faithless?", objectives = "Speak with Nisha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49665] = { id = 49665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready to Riot", completion = "Look at my people fighting! The Faithless don't stand a chance!", objectives = "Free and arm 8 Vulpera Slaves in cages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49666] = { id = 49666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Fear Us", description = "I carry this banner into every battle because I want the Faithless to fear it. To fear my people.\n\nIf I die in the battlefield, surrounded by Faithless, I will die happy.\n\nOn that day, I will not need a burial or prayers. But I will need someone to pick up my banner and carry it into the next battle.\n\nIf you are of the same mind, plant these banners into the corpse of every Faithless you slay. Let the survivors know who's coming for them.", completion = "And that's just the start! Now the Faithless know who's coming for 'em.", objectives = "Plant 12 Vulpera Banners into dead Faithless.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49667] = { id = 49667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Little Ones", completion = "Thank you, thank you, thank you!\n\nThese children have already experienced more hate and pain than anyone ever should. I'll make sure they feel love in equal measure.", objectives = "Kill Appraiser Versik and lead the vulpera kids back to Meerah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49668] = { id = 49668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Up the Gulch", completion = "The fires are spreading quickly. Let's hurry, while the Faithless are distracted.", objectives = "Torch the slave auction sites in Slithering Gulch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49669] = { id = 49669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash the Beasts", description = "The Faithless are arrogant hoarders, capturing people and beasts that can never be truly tamed. All to fuel their endless lust for war.\n\nI've even seen their slavers dragging blood trolls and other dark monsters from the swamps of Nazmir.\n\nI heard terrible noises coming out of a cave while I was scouting the feeding pits up ahead.\n\nWhatever monsters they are hiding in there, find a way to free them and let them exact revenge on the Faithless.", completion = "Crawgs are violent, filthy things... Yet another reason to avoid Nazmir.", objectives = "Kill Tamer Traskniss to release the crawgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49676] = { id = 49676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressed for Battle", description = "Kiro's the leader of my caravan. He's always been far too passive.\n\nI warned him we needed to make a preemptive strike against the sethrak, but he insisted that we keep our heads down and continue to quietly do business.\n\nLook where that got us.\n\nOur caravan was completely unprepared for their attack. \n\nNow I'm ready to fight for what's ours, but I'm not exactly dressed for battle.\n\nHelp me scavenge some suitable equipment here among our enemies. We will use their own tools against them.", progress = "Killing an enemy with their own sword is an even bigger insult, no?", completion = "Now we are ready for a real challenge!", objectives = "Help Nisha find a war banner, a helmet, and explosives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49677] = { id = 49677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plans for Attack", description = "Before we were attacked, I had a plan to take the fight to the sethrak. \n\nIt was devised with flawless intel. I know, because I gathered the information myself. \n\nI surveyed their entire compound and created a map based on my findings. \n\nMy plan relies on that map, but it's now in the hands of Fangcaller Sraka, the brute who's leading this assault on my home.\n\nHelp me kill her so I can take back what's mine!", progress = "My plan for attack is both detailed and dangerous.", completion = "These plans will be our key to taking the fight to the sethrak.", objectives = "Recover Nisha's Attack Plans from Fangcaller Sraka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49678] = { id = 49678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Spy a Spire", description = "It is good you have come. Dol'watha be under attack by these snake-men.\n\nSoon as they arrived they started pulling these weird spire-things out de ground. I seen a bunch of snake-mons with feathers in their caps getting zapped by them, but they not be dying.\n\nIf it not be bad for them, that means it's good for them. And that be bad for us.\n\nDestroy those spires. Hopefully whatever boon they be getting will go away and they will be easier to kill.", completion = "Not so much static in de air now. That's good. Means we did something right.", objectives = "Destroy 4 Sethrak Spires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49679] = { id = 49679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sethrak Incursion", description = "Dol'watha be a small village. Got a few farms, some beasts, and a decent view of a swamp.\n\nLoa know we not be ready for this...\n\nDe snake-men popped out of de ground by de hundreds. Slaughtered my beasts, my family, my friends. One minute de earth rumbling, de next we be running for our lives.\n\nI heard about snake-men from de deserts of Vol'dun but I never believed I would see them in my life...\n\nHelp us fight back. Kill as many of them as you can. Dol'watha won't be beaten that easily!", completion = "Won't bring back de ones we lost, but it show them that not even little Dol'watha be going down without a fight.", objectives = "Slay 12 sethrak in Sandscar Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49680] = { id = 49680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skycaller Soltok", description = "As if snake-men with swords not be bad enough, they brought a powerful skycaller along.\n\n I hear skycallers can tempt great storms into being. They be to blame for de spires and lightning flying everywhere.\n\nThere be one who wear a bigger feather than most, likely de leader. Calls herself Soltok or something equally hissy.\n\nDon't care. Kill her.", completion = "Good, very good...", objectives = "Slay Skycaller Soltok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49681] = { id = 49681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lil' Tika", description = "<The tiny armored raptor scratches pitifully at the cage's wooden bars. As you approach, the miniscule reptile wiggles frantically and issues a piercing screech for help!\n\nPerhaps you can open the cage and let it free.>", progress = "My poor beasts...", completion = "Why is she covered in blood?\n\nOn secon' thought, nevermind.\n\nPraise all deh loa, at least dis little one made it!", objectives = "Rescue Lil' Tika.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49694] = { id = 49694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn to Drust", description = "There are blood scribe masters all over the place who'll teach you what you need to know. The first master I'd recommend seeking out is Kronah.\n\nShe's a bit... eccentric to say the least. One of the few tortollan who've experienced a thing or two.\n\nShe's the one who taught me the blood contract I know how to invoke!\n\nShe likes to hang out at the Smuggler's Cove on the western coast of Drustvar. Oh, and could you say hi for me when you see her?!", completion = "<Kronah eyes you up and down warily.>\n\nSay ahhh for me, would you young one?\n\n<Kronah peers inside your mouth.>\n\nNice teeth you have there. Would fetch a fine price. But that's not really what you're here for, is it?\n\nNo, you're one of those who think they can handle the trials of the blood contracts, aren't you? Very well.", objectives = "Seek out Kronah at the Smuggler's Cove in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49698] = { id = 49698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lightforged", description = "Do you wish to hear how the Lightforged draenei joined the Alliance? It might be one of my favorite stories.\n\nMost likely since it involves seeing our beautiful world from space!\n\nIt all began when High Exarch Turalyon invited members of the Alliance onto the Vindicaar...", progress = "This ritual has never been witnessed by an outsider.", completion = "Welcome, {name}. You are about to bear witness to a ritual none but members of the Army of the Light have seen.", objectives = "Travel to the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49703] = { id = 49703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House Stormsong", description = "I have little information to offer, I'm afraid. I've scarcely left Brennadam as of late.\n\nWhat they said is true. Our militia now enter town only to collect rations rather than guard traders or keep the quilboar at bay.\n\nThey say they are under orders, but those orders would only come from my brothers at the Shrine. We take oaths to serve our people... it simply does not add up.\n\nBrother Addington is nearby at Mariner's Strand. Perhaps he knows more than I.", completion = "What has become of our people...", objectives = "Meet Brother Pike and Taelia at Mariner's Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49704] = { id = 49704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haywire Harvesters", description = "See the golems down there? Farmers use their sharp claws to reap the harvest, but these are cutting timber... \n\nWhy would they need them here when they have so many laborers on hand?\n\nI think the militia is using them to intimidate their own people!\n\nSee if you can get ahold of an intact mainspring from one. I've helped repair a few back in Boralus. I should be able to figure out who is messing with their innards.", progress = "Any luck? The mainsprings are usually brittle and easily damaged.", completion = "Perfect! Here, let me take a closer look.", objectives = "Obtain a Drenched Mainspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49705] = { id = 49705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnecessary Duress", description = "Lord Stormsong has never taken kindly to dissent, but this is madness. These laborers are being worked to death!\n\nAddington was a good man. We cannot stand for such cruelty.\n\nTake this vial and apply it to the laborers. It contains blessed seawater that will rejuvenate their strength.\n\nAvoid engaging what troops you can. They are merely following orders. More death will only worsen matters.", completion = "There is much work to be done, but not at the cost of our own people's lives.", objectives = "Rejuvenate 8 Exhausted Laborers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49706] = { id = 49706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proclamation Investigation", description = "My lord seldom leaves our holdings along the northern coast, and visitors are expressly forbidden. For most, tidesages like myself are their only connection to the house proper.\n\nLord Stormsong usually delivers orders through proclamations posted throughout the valley. None have reached Brennadam, but if there are any posted here we may be able to find some answers.", completion = "Independence?!\n\nThis is too far. A shattered Kul Tiras will never stand!", objectives = "Read 3 Stormsong Proclamations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49710] = { id = 49710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering of Eggs", description = "Our work isn't only to capture and tame gryphons, it's also to preserve them.\n\nRescue any eggs remaining in nearby abandoned nests. Set them in one of the new nests we've built for the displaced gryphons. I am sure one of the gryphon females will adopt them.", progress = "You find a safe nest.", completion = "The eggs fit nicely into the new nest.", objectives = "Collect 4 Spotted Gryphon Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49715] = { id = 49715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Greystone Keep", description = "A friend of mine, a fellow military courier, had a job at Greystone Keep. The fort lies just outside of Boralus, so I would've expected him to be back by now.\n\nI have another job lined up, so could you go check out the fort for me? I'm probably just being paranoid.", completion = "A courier? I think we lost him in the coup.", objectives = "Speak with Tallis Skyheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49716] = { id = 49716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson on Trust", description = "The men in the fort were once under my command, and so, they are now my responsibility. Each of them should have a badge we use for identifying individuals under certain circumstances. I would ask you to bring back a number of these as proof of thinning their ranks.\n\nThese men are no longer soldiers of Boralus, and as such, no longer deserve to carry the Proudmoore anchor.", progress = "Did you bring me those badges?", completion = "A grim task, but one that needed to be done.", objectives = "Retrieve 8 Marine Identification Badges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49719] = { id = 49719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Paid", description = "Now that we got our mitts good and bloody, I think it's time we head back to camp.\n\nI'll run ahead, so you can finish up whatever business you got. Just remember to meet Tagart for your pay.", completion = "Here's your pay. You seem suited for the Roughneck life. Come back sometime if you need work.", objectives = "Meet with Tagart at the Roughneck Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49720] = { id = 49720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Bird", description = "Skyheart invited me here to teach some of his city boys how to train the local sea hawks. Some of my students went and sided with the mutiny force. Seems these soft marines have forgotten what the consequence is for betraying a Drustvar soldier.\n\nWorse yet, they've locked up quite a few of the younger birds we were training. I've got my hands full with these hawks, so if you could free a few of the young'uns while you're in the fort, I'd appreciate it.", progress = "Any luck? Hopefully they didn't nip you too much.", completion = "My birds deserve better partners than men who betray their own country.", objectives = "Free 5 Juvenile Seahawks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49725] = { id = 49725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Risky Ploy", description = "Things are worse than we thought. These people are about to tear Brennadam apart!\n\nWe'll never get a chance to talk to Brother Pike in this mess.\n\nI have an idea, but if it doesn't work, well... I hope you have your running boots on.\n\nTrust me?", progress = "We haven't had visitors here in quite some time.", completion = "Ah, Brother Alen sent you. Good.", objectives = "Disperse the crowd surrounding Brother Pike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49730] = { id = 49730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Thundersnout", description = "Thundersnout is the largest of the boars in the valley. She is wreaking havoc on the nearby farms and their crops.\n\nMayor Roz of Brennadam has issued a bounty for proof of her demise.\n\nThundersnout's location is near Briarback kraul, so be on the look out for quilboar!", progress = "Yes?", completion = "The death of the matriarch means the next generation of boars will be delayed. Nice work.", objectives = "Deliver Thundersnout's Snout to Mayor Roz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49731] = { id = 49731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fond Farewells", description = "Dis is where we part ways, {name}.\n\nI'm going to take de name Akunda, and start a new life here. \n\nRakera saved my life, and I'm going to make sure to live a life dat was worth saving. \n\nIf you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.", progress = "What is dis?", completion = "<B'wizati reads the note and wipes a tear from her eye.>\n\nHe may choose to forget, but I choose to remember, no matter what pain it brings me. \n\nAt least he is safe. Loa watch over him.", objectives = "Deliver Jorak's Note to B'wizati in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49733] = { id = 49733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patching Up the Rear", description = "Most of my men were injured when we were escaping the fort, those that weren't were injured holding this position.\n\n<Tallis hands you a stack of stained cloth.>\n\nAll of our better supplies are behind those walls, so we've been forced to make do with what we have. Everything that's not being worn on a soldier's person as we speak has been shredded for use as bandages. We don't have the staffing to take care of everyone.\n\nHead out and replace the worst of our injured's bandages.", progress = "My gratitude, that should help alleviate some of the soldiers' pain.", completion = "My gratitude, that should help alleviate some of the soldiers' pain.", objectives = "Bandage 5 injured marines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49734] = { id = 49734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Targeting a Turncoat", description = "The instigator of this mutiny is a man named Fernn. He has always shown discontent with House Proudmoore and his position here. But to betray the men he works with? That seems beyond even my expectations of him.\n\nTake him out, and show this mutiny the mistake of crossing truly loyal marines.", completion = "Good work. That should be enough help to get my men back in that fort and manning it again.", objectives = "Slay Fernn the Turncoat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49735] = { id = 49735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect the Nests", description = "Now that Tagart is done with your hazing... I mean... trials, you can start helping us with some of the work around here.\n\nSome of the nearby gryphon nests have been overrun with saurolisk. I fear that the gryphons will make new roosts elsewhere if we don't clear them out.\n\nHead up the road towards the waterfall and take out those saurolisks. Report to Shawn when you're done. He's posted as a lookout there.", progress = "Get bit?", completion = "Bloody saurolisks. Good riddance.", objectives = "Kill 7 Hungry Dewscale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49736] = { id = 49736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Kul Tiras!", description = "Listen, I'll be frank with you; we're not at full strength here. Many of our soldiers recently left for Boralus on new orders.\n\nIt's like they knew just when to hit us...\n\nBut we're going to hit back! Every able-bodied man and woman in town has stepped up to mount a defense.\n\nTake this battle standard and remind them what they're fighting for!", completion = "It fills my heart with pride to hear that battlecry ring out across the field.", objectives = "Use the Proudmoore Battle Standard to inspire 15 Vigil Hill Marines or Militia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49737] = { id = 49737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Air Raid", description = "Those pirates have air support! They're torching our farms and splitting our attention away from the front lines. \n\nTake 'em outta the sky!", completion = "Damn fine work! I'll recommend you for a medal of valor!", objectives = "Slay 6 Irontide Skyriders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49738] = { id = 49738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hands Off My Booty!", description = "We are dealing with lawless, no-account thugs. As soon as they gained ground, they started looting! Looting right in the middle of a battle!\n\nWell I, for one, am not giving up our booty that easily.\n\nGet up to the top of Vigil Hill and man the main cannon. Rain hellfire down on those blaggards!\n\nDismissed!", progress = "What are you waiting for? Get up there and man that cannon!", completion = "They destroyed the main gun?!\n\nThen it's time to advance on foot!", objectives = "Man the Vigil Hill Cannon and use it to slay 20 looters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49739] = { id = 49739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies at the Gate", objectives = "We'll recover the loot from that ship later, assuming the whole thing doesn't burn down or sink first!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49740] = { id = 49740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cease Fire!", description = "The enemy has turned our forward cannons around on us.\n\nScuttle that equipment to stop the bombardments!", completion = "The thunder of cannons can strike fear or inspire hope, depending on which end you're standing.", objectives = "Destroy 4 Captured Cannons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49741] = { id = 49741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righteous Retribution", description = "Cyrus taught me how to deal with thugs, bullies, and scum like pirates.\n\nWhen they hit us, we hit back twice as hard.\n\n<Taelia's hand finds the haft of her hammer and grips it tight.>\n\nIt's time to hit back.", completion = "Those cowards only understand strength. Show them you're not an easy victim and they turn tail and run.", objectives = "Help Taelia destroy the pirate ships in Daelin's Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49744] = { id = 49744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs, Away", description = "By the sea's foamy beard, what a blast!\n\nThey've brought goblins, and if there's one thing I know about goblins it's that they like to blow things up.\n\nI saw a few of them carrying large bombs, and I presume that they are going to blow up the town. I would like to keep the town, so how about you head out there and steal as many of those explosives as you can find? After that, let's blow up their demolishers and stop this infernal bombardment!", progress = "Don't forget to check inside the buildings too!", completion = "These look particularly nasty. I'm glad they aren't blowing up in our faces.", objectives = "Retrieve 8 Horde Explosives and use them against the Demolishers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49745] = { id = 49745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Have Their Orders", description = "The Horde is an army, make no mistake. And armies need orders.\n\nSomeone must be giving orders here. They know the plan, and I want to know the plan too.\n\nLook for the people who seem to be in charge and see if you can uncover any intelligence so we know what to do next.", progress = "You find those orders?", completion = "The Banshee Queen is not like the previous Warchiefs.", objectives = "Find the Warchief's Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49746] = { id = 49746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dousing the Flames", description = "The Horde have set fire to my town, {class}. I will make them pay for this.\n\nStormsong Valley is the breadbasket of Kul Tiras, and our people need to be fed. The first thing we must do is damage control.\n\nGrab some buckets and help put those fires out!", completion = "Bombs, fire, Horde. Our town will endure it all.", objectives = "Use the Water Bucket to put out 15 fires around the Ruins of Brennadam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49753] = { id = 49753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contruct Armory" }
quests[49754] = { id = 49754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not \"Only Zul\"", description = "Our enemies here either follow de name of Zul, or dey want to use him to take Zandalar.\n\nHe has the ego to allow either. \n\nDey claim only Zul can lead us.\n\nDissuade dem.", progress = "Did ya leave any breathing?", completion = "Well done, {name}. I wish that put a bigger dent in the threat they pose.", objectives = "Purge Zul's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49755] = { id = 49755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Artillery", description = "Bad news, friend. They're bringing in serious firepower now.\n\nWe've spotted a tank on the northern hill by the windmill. They can reach the other side of the town from there. We can't let them set it up.\n\nWhat do you say to giving them a taste of their own medicine? If you can take out their commander, you'd have a fancy new tank all to yourself. Imagine the mayhem you could unleash on their invasion!", progress = "If that cannon can reach Brennadam, it can reach those zeppelins!", completion = "Those were some explosions! I'm just glad they were directed at the Horde and not us.", objectives = "Slay Captain Wormwood and commandeer the Experimental War Machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49756] = { id = 49756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Forces", description = "The Old Gods have inflicted one of their faceless ones upon Thunder Bluff. The fiend desecrates my people's city!\n\nWe must fight together to rid this place of such filth.\n\nI believe that destroying this herald will drive our enemies from Mulgore. May our weapons strike true, {name}!", progress = "This herald of the Old Gods must be stopped.", completion = "A fine kill, {name}. My people can clean up from here.", objectives = "Defeat Qy'telek, Herald of Uul'gyneth", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49757] = { id = 49757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cat on a Hot Copper Roof", description = "My parents said we have to go, but I won't leave Scratchy behind!\n\nShe's so gentle and precious and pure and kind and soft and cuddly! She must be so scared up there on the balcony!\n\nPlease help her!", progress = "We can't leave Scratchy here!", completion = "Yay!\n\nIsn't she the sweetest most perfectest kitty cat ever?!", objectives = "Climb the burning house and rescue Scratchy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49758] = { id = 49758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send the Signal!", description = "My crew is not on board with de word of Zul. We saw too much of who he really is. \n\nFar out in de harbor, Zul's traitors have joined with de mogu to try to take my ships! If we lose de fleet and de harbor, we lose de city!\n\nWe must let Zuldazar know we stand strong. We take back de ships. We drive de villains out. \n\nYou must light de towers with loa-blessed flame. Dey will always see dat de Bay of Kings belongs to Zandalar!", completion = "Ya got here just in time!", objectives = "Get to the ship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49759] = { id = 49759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contruct Workshop" }
quests[49766] = { id = 49766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Next Move", description = "We have some thoughts on the best way to win over the Zandalari.\n\nThe princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father.\n\nGeneral Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here.\n\nWe should also keep working on winning over the King here in Zuldazar. This city is vast and has many secrets.", sourceObjective = "Choose your next move in Zandalar.", sourceObjectiveStatus = "unverified-source-field" }
quests[49767] = { id = 49767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Next Move", description = "We have some thoughts on the best way to win over the Zandalari.\n\nThe princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father.\n\nGeneral Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here.\n\nWe should also keep working on winning over the King here in Zuldazar. This city is vast and has many secrets.", sourceObjective = "Choose your next move in Zandalar.", sourceObjectiveStatus = "unverified-source-field" }
quests[49768] = { id = 49768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwary's Trek", description = "De greatest hunter from your lands, de dwarf Nesingwary, has come to participate in de Great Hunt.\n\nIf you are enough of a hunter to join him, den travel to de Nesingwary Trek along de northeastern region of Zuldazar.", completion = "Welcome to tha hunt.", objectives = "Speak with Hemet Nesingwary at Nesingwary's Trek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49769] = { id = 49769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wreckage of the Cataclysm", description = "In recent years one of the greatest Zandalari loa temples mysteriously fell into the sea. It is a topic of some debate what caused this, and what treasures might have been lost in the catastrophe.\n\nMy cousin Rokor was in charge of the salvaging efforts. Within the temple were many great items of knowledge and power. I am sure he will have need of the services of someone like yourself with strong arms and working knees.", sourceObjective = "Find Rokor at Scavenger's Strand.", sourceObjectiveStatus = "unverified-source-field" }
quests[49772] = { id = 49772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Alliance", description = "The Army of the Light was founded with one purpose: to defeat the Legion. Though we have achieved that goal, a new duty lies before us.\n\nAzeroth is a world beset by enemies. Use your training to battle the darkness and uphold the ideals of the Alliance.\n\nGo to Stormwind. Seek the king's ambassador at the embassy, then set out to spread the Light's justice across the land.\n\nPheta thones gamera, {name}.", completion = "What have we here? One of the famed Lightforged draenei! Welcome, welcome.\n\nThank you for your service against the Legion, {name}. Truly an inspiration!", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49773] = { id = 49773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Horde", description = "A new age dawns upon Highmountain, {name}.\n\nAfter centuries apart, the bond with our kin from Kalimdor has been reforged. And in the fight to save our land, we found new friends among the people of the Horde.\n\nTo show the strength we bring to our allies, brave tauren like you must heed the call of adventure.\n\nYou have been invited to Orgrimmar. Meet with the ambassador at the warchief's embassy, then begin your journey across Azeroth.\n\nEarthmother be with you, {name}.", completion = "Are you the new one? I'm supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>", objectives = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49774] = { id = 49774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Won't Leaf Him to Die", description = "I may have done some wicked things in my past, but I won't leave dis guard to die.\n\nZulajin has taken a nasty bite outta Zaluto... and has also infected him with some weird voodoo.\n\nBut don't worry, because today is our lucky day. I have a plan to cure him. Dere are sweetleaf bushes nearby!\n\nDe leaves of dis bush are known for their healing properties. You get me some, and I will be able to save dis Zaluto.\n\nIt's de only chance we have!", progress = "Did you get de sweetleaf?", completion = "You have de sweetleaf! Looks like you gathered just enough, too!", objectives = "Gather 8 Sweetleaf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49775] = { id = 49775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Key to the Brig", description = "You can tell a lot about a troll by what they do when they learn who Zul truly is. \n\nThat Garza is a mutinous, foul-tusked, ship stealin' traitor. She is the kind of zealot dat will follow de heretic into the maw of an Old God. \n\nI am more de type to rip out her tusks and beat her with dem. \n\nI'd settle for ya taking her key and getting our wavemaster and crew free!", progress = "Did ya relieve her of de key?", completion = "Garza was lost long ago. It sounds that Maset is as feisty as ever. We will get out to de ships!", objectives = "Get the key from Quartermaster Garza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49776] = { id = 49776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Problem Tar Can't Solve", description = "I'm not going to lie... I did wicked things in my youth and I've been living with de shame ever since.\n\nBut Zaluto is going to die without my healing, and we're all going to die if dat dino isn't taken care of.\n\nDere is a lot of tar in dis area. I need it to cure Zaluto of whatever is infecting him here.\n\nGet me dat tar, and I'll be able to save Zaluto from dis fate.", progress = "We will need plenty of dat sticky tar!", completion = "Good job! Dis is exactly de kind of stuff we need!", objectives = "Collect 6 Sticky Tar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49777] = { id = 49777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On The Run", description = "<The guard captain appears to be fatally wounded.>\n\nWe were... transporting prisoners when de ambush came... a giant devilsaur... tore through everything.\n\nMost of de prisoners escaped in de carnage... dese are hardened criminals. Dey cannot be allowed to roam free!\n\nI swore a blood oath dat I would deliver dem to Vol'dun... I am probably going to die here, but I will not die an oathbreaker!\n\nFind de escaped criminals and exile dem to Vol'dun.", progress = "Have you found de escaped prisoners?", completion = "You have my thanks... if I die here, at least I can face my ancestors with my oath fulfilled.", objectives = "Exile the escaped prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49778] = { id = 49778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Go into the Light", description = "Okay, dis is de moment of truth! We will see if my voodoo can cure Zaluto.\n\nI should have been honest with you... dere is a chance dis won't work. Voodoo isn't a science, you know.\n\nI need you to hold Zaluto down, because dis here is going to hurt. A lot.", progress = "We can't leave Zaluto to die.", completion = "Zaluto is free from death's door, but he's still weak. We have more to do.", objectives = "Hold Zaluto down while Jin'Tiki cures him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49779] = { id = 49779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad To The Bone", description = "I will not leave here without killing Zulajin, or else it will just go after de next caravan dat comes through.\n\nI have a plan, but we must work together to pull it off.\n\nDere are skeletal raptors roaming in de area. I do not know what voodoo brought dem here, but we need dem gone.\n\nWe are going to need as much space as possible for my plan to kill Zulajin.", progress = "Did you take care of de skeletal raptors yet?", completion = "You have done well taking care of de bone raptors. Even if dis road is only for criminals, dey at least deserve to make it to Vol'dun alive.", objectives = "Slay 10 Bone Raptors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49780] = { id = 49780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering Ancient Fire", description = "Zaluto has a crazy plan to kill Zulajin. Never thought a guard could come up with something so clever.\n\nDere is ancient mojo throughout dis place... who knows what it used to be? But I sense something I can use.\n\nDe statues sinking in de tar pits have de fire mojo still burning in dem. We will need it to kill Zulajin.\n\nTake my fetish and use it to absorb what's left of de fire in dese statues.\n\nJust don't get dat fire too close to de tar!", progress = "Do you have de fire yet?", completion = "De fetish is brimming with de fire magic! Good, because you will need it for what comes next.", objectives = "Absorb fire mojo from 4 Nazmani statues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49781] = { id = 49781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch Me if You Can", description = "Alright, de time has come for you to face Zulajin yourself!\n\nJin'Tiki's fetish has de power of some ancient fire in it now. You will ride my raptor here to lure Zulajin into de tar pits.\n\nAfter dat... you will use de fetish to light de tar pits on fire! Dat should be enough to kill Zulajin.\n\n...and if not, well, den you will have to improvise. Good luck!", completion = "I knew you'd take care of Zulajin, no problem! I guess it is time for me to say goodbye to de jungle once and for all...", objectives = "Ride Zulato's raptor to lure Zulajin into the tar pits and set it on fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49782] = { id = 49782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Lightforged", progress = "Welcome aboard, {name}.", completion = "Duty. Honor. Sacrifice. The Lightforged strive to embody these qualities. You have done so with aplomb.\n\nIt is my pleasure to award you with a symbol of your service, {name}.", objectives = "Meet Captain Fareeya aboard the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49783] = { id = 49783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of Highmountain", completion = "You have brought great honor to our tribes, {name}. It is fitting that we give you a symbol of our thanks.\n\nHighmountain stands... because you have the courage to fight for it.", objectives = "Meet Mayla Highmountain in Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49784] = { id = 49784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Nightborne", description = "You are among the first shal'dorei to venture forth and explore the wilds of Azeroth. But now it is time to come home.\n\nReturn to Suramar so that we may thank you for helping our people reclaim a place in this world.", completion = "When we were liberated from the Legion, some among the shal'dorei believed we should remain isolated. Alone.\n\nYour accomplishments in Azeroth have shown that we made the right decision in reclaiming our place in this world. It pleases me to honor you with this symbol of Suramar's gratitude.", objectives = "Meet First Arcanist Thalyssra at the Nighthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49785] = { id = 49785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Weapon", description = "I did scout de next island. Rezan's Claw has a mighty weapon on board.\n\nI don't know what it is, but dey are confident in its ability to break de defenses of our home.\n\nGet to de ship. Destroy that weapon before dey can use it on Zuldazar!", completion = "Dat was unexpected.", objectives = "Investigate the weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49787] = { id = 49787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ghostlands", description = "Are you familiar with how the Void elves joined the Alliance? \n\nIt began with Alleria Windrunner finding out about a blood elf named Umbric. \n\nHe and his followers were banished from Silvermoon City for researching void magic.\n\nAlleria believed she could convince Umbric and his followers to join the Alliance and prevent the void from corrupting them.\n\nIt all began when she opened up a portal to go into the Ghostlands...", progress = "These lands bring back memories. Some good, some bad.", completion = "Umbric's methods are a bit cavalier, but he seems competent. We must get to him before things become too dangerous.", objectives = "Locate Umbric's home in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49788] = { id = 49788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Alliance", completion = "Ah, there you are, {name}! We've been inspecting--err--expecting you!", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49789] = { id = 49789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pledge", description = "The ethereals were lying in wait, anticipating someone strong enough in the void to be corrupted by the influence of the Old Gods.\n\nWe arrived in time to save them, and I will help teach them how to resist the whispers.\n\nUmbric is ready to join the Alliance. Let us return to Stormwind and inform King Wrynn.", sourceObjective = "Return to Stormwind and speak with Anduin.", sourceObjectiveStatus = "unverified-source-field" }
quests[49791] = { id = 49791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost, Not Forgotten", description = "I know not what madness has overtaken my people, but we must stop it together.\n\nTake this bell. It calls the souls of the recently deceased to it for later release. We Stormsong do not bury our dead in the earth. The tides claim all.\n\nIf they will not answer to reason, then we must give them eternal peace. Fallen or not, they are Stormsong.", progress = "It is a grim task, but it is our burden to bear.", completion = "It is done. We will release them somewhere a bit more peaceful.", objectives = "Recover 12 souls using the Dead Ringer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49792] = { id = 49792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound and Oppressed", description = "We had our orders: ships, and lots of 'em. I led my boys as best I could.\n\nEverything changed when the tidesages showed up. We figured they was just checkin' on our progress, but the hood-wearin' bastards turned on us!\n\nThese anchors bind us here, forcin' us to work to death. No one deserves a fate like that. You gotta free my boys!", completion = "I owe you one, stranger!", objectives = "Destroy 8 Anchors of Binding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49793] = { id = 49793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Means to an End", description = "In our haste to journey here I did not think to bring my ritual implements we tidesages use to augment our power.\n\nTo be honest, I had never expected them necessary on what should have been a peaceful sojourn.\n\nAddington does not have his, either. I am sure the militia took him from his home before he had the chance to react.\n\nThat means his implements should still be in the yard somewhere. We must find them before my power is of much real use.", progress = "We must find a full set of ritual implements. I fear we will have need of them.", completion = "Those initiates were nowhere near ready to wield our sacred implements. They are far better served in our hands.", objectives = "Retrieve Brother Addington's Tidal Kris, Abyssal Beacon, and Wavecaller's Mantle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49794] = { id = 49794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rising Tide", description = "This mainspring wasn't altered by an engineer. These runes on the surface can only have come from a tidesage.\n\nTheir aquatic magic is unmistakable. I'd bet whoever did this is also responsible for Addington's death.\n\nWhoever they are, they're likely still nearby. Keep an eye out... they won't be hard to find.", completion = "This does not bode well.", objectives = "Seek revenge on Sister Ava.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49800] = { id = 49800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Spiders!" }
quests[49801] = { id = 49801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Mating Strategy", description = "Aggression is good. I agree with Jangalar that Ben'jin needs to be a lot less passive to succeed and I can prove science is the way to do it by making an injection for him.\n\nAlchemy tells us that, for this type of beast, aggression comes from a substance in their bile sacs. The local razorwings are invasive and, as such, have more than enough aggression for our purposes. \n\nHarvest some of their bile sacs and I'll make a treatment that will have our big boy ready to go again in no time.", progress = "Did you get all of the bile sacs I need yet? Science is not supposed to be safe...", completion = "Just what I needed! Boy do they smell! \n\nWith these bile sacs, I can make enough Aggression Formula for a creature as big as a brutosaur.", objectives = "Harvest 8 Bile Sacs from Invasive Razorwings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49803] = { id = 49803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing of the Guard", description = "I have no doubt that you're a quite capable {class}, mainlander, but we will need some help if we want to make it to Waycrest Manor in one piece.  A small group would be ideal; strong enough to face the coven's threats, but small enough to remain largely unnoticed.\n\n<Reade produces a bundle of letters.>\n\nI have written new orders to some of my finest soldiers to join your Order of Embers. They will report to you and the lady Waycrest. Please deliver these to them, so they can be prepared to move out.", progress = "You will need to gather your recruits before we venture forth.", completion = "It is with reluctance that I hand command of these men over to you, but it must be done.\n\nI hope you lead them well.", objectives = "Deliver recruitment orders to Captain Cleardawn, Ensign Yorrick, Ensign Mace, Lieutenant Sterntide, and Falconer Notley in Arom's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49804] = { id = 49804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharp Thinking", description = "I have reason to believe that the coven has already infiltrated Arom's Stand. There are many unfamiliar faces here, with the refugees from Corlain, and we know they can use their magic to appear like one of us.\n\nThis needle is fashioned of solid silver. If the witches are indeed vulnerable to silver, then a prick from this may be enough to break their spell. \n\nThe refugees may not be keen on being prodded, but they must understand that this is for the good of the town... and perhaps all of Drustvar.", progress = "I really hope this works...", completion = "It worked?! I knew we were on the right track!\n\nIt's too bad we don't have a stockpile of silver weapons lying around, but I think I know how we can deal with that.", objectives = "Use Lucille's Sewing Needle on 10 Corlain Refugees to reveal the hidden witches in Arom's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49805] = { id = 49805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Implements of Ill Intent", description = "<It looks like some careless witch made a poor attempt to hide this grimoire from sight. No good could come of leaving the possessions of the coven for a hapless villager to find.\n\nIt would probably be a good idea to destroy any trappings of the coven that you find in Arom's Stand.>", completion = "That was good thinking to dispose of the witches' trappings. \n\nI don't want to know what would happen if an innocent villager toyed around with such things!", objectives = "Destroy 12 Heartsbane objects in Arom's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49806] = { id = 49806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Dealings", description = "<Among her possessions, the witch carried a crudely drawn map of Arom's Stand. \n\nA symbol marks what looks like the entrance to a cellar beneath one of the buildings.\n\nIf this location is important to the coven, it might be worth scouting out.>", progress = "What's this? A map?", completion = "You found their leader? Excellent work, {class}!\n\nThe people of Arom's Stand will be safe, now that you've so thoroughly dismantled the coven's machinations here.", objectives = "Explore the location marked on the Crude Map.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49807] = { id = 49807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Order", description = "Before we leave, I have one more task to ask of you.\n\nWhile you were busy recruiting our inquisitors and driving the coven away from Arom's Stand, I took the liberty of placing an order with the local tailor. \n\nUsing some of the sketches within the tome, I had him put together some uniforms reminiscent of those worn by the ancient order.\n\nSince you will be leading our inquisitors, I think it's only fitting that you present them with their new regalia.", progress = "You should be inducting them, not me!", completion = "There, that was nice and official. \n\nNow, I think it's time we took the fight back to the Heartsbane. I believe the marshal has a plan.", objectives = "Give the Inquisitors Regalia to the recruits in Arom's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49809] = { id = 49809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: From the Shadows" }
quests[49810] = { id = 49810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monstrous Matchmaker", description = "We have a problem, a matter of love, and you've come just in time. \n\nTwo white brutosaurs, de male Ben'jin and de female Maka'fon, are de last of their kind. De rest have passed on. \n\nDese two are not in de mood for love. If you can help my new friend Cala and myself, dis may be de only chance to give dem a future. \n\nPlace my voodoo totem close to each one so dat I can feel what dey feel and learn how we can help.", progress = "Place de voodoo totem close to both of de brutosaurs and I will be able to sense what dey feel.", completion = "We need to help Ben'jin to get his mojo back and Maka'fon to be in de mood. Is voodoo or science de better way to go?", objectives = "Place Witch Doctor Jangalar's Voodoo Totem near both brutosaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49812] = { id = 49812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delas in Dalaran", description = "Delas Moonfang needs our help. In-turn, she will aid us to decrypt the Codex of Command.\n\nI implore you to seek her out as soon as possible. She is known to enjoy the memorial dedicated to the fallen, great leader of the Kirin Tor, Antonidas.", completion = "Goddess be praised that you are here, {name}. I'm hoping that you can aid me.", objectives = "Find Delas Moonfang at the Antonidas Memorial in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49813] = { id = 49813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventure Calls", description = "Tales of your heroism have spread to the ends of Azeroth... and beyond. Your skills have been requested elsewhere.\n\nWill you travel through the Dark Portal, fighting the Burning Legion on the sundered world of Outland?\n\nOr will you fly north, joining the battle against the Lich King in Northrend?\n\nThe choice is yours, adventurer.", objectives = "Use the Special Duty Assignments to select your next adventuring destination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49814] = { id = 49814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent for a Brutosaur", description = "Mood is everything for love, and Maka'fon is not in de mood. \n\nVoodoo incense, specially formulated for brutosaurs by an expert witch doctor like myself, will surely spark de fire of de mother spirit in her heart. \n\nCertain fragrant rushes work best, and de jungle will provide. \n\nZandalari rushes grow near de waters here. Get a good amount for me and I will make an incense bundle big enough to set de mood.", progress = "Look for de rushes near de life-giving waters dat I might use my voodoo to make incense for de brutosaurs.", completion = "Well done! I will weave dese rushes into incense bundles and cast my best spells upon dem.", objectives = "Find 7 Fragrant Rushes to make incense for Irritable Maka'fon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49816] = { id = 49816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: To Outland!", description = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the orcs. Adventurers of the Horde are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.\n\nTravel to the Blasted Lands, and pass through the Dark Portal.", objectives = "Go through the Dark Portal in Blasted Lands.\n\nThe Thrallmar Mage in the Orgrimmar Portal Room can help you get there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49817] = { id = 49817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Northrend!", description = "The Lich King stirs in the north.\n\nAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.\n\nWe need you to stop them, {name}.", objectives = "Take a zeppelin to Northrend.\n\nYou can board the Howling Fjord zeppelin in Tirisfal Glades, or the Borean Tundra zeppelin in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49818] = { id = 49818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Fort Daelin", description = "I was sent to Brennadam by my commanding officer to find a tidesage to help us at Fort Daelin to the west. The naga have started another attack on the bastion, and it's larger than any we have seen. \n\nLieutenant Bauer is in the middle of helping out civilians at the village near the fort, and she could use any help possible.", completion = "These fishermen are no pushovers themselves. They should be able to hold their own here with a little help.", objectives = "Report to Lieutenant Bauer at Seabreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49831] = { id = 49831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Depths", description = "We must prepare for an attack.\n\nMan the cannons!\n\nDefend the levee at all costs!", completion = "We've done it! The naga are defeated and the levee remains intact!", objectives = "Defend the levee from the Azshara's assault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49832] = { id = 49832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Illegible Scroll", description = "<Resting within the waterproof container is an illegible scroll of undetermined age and origin. \n\nPerhaps the tortollans along the coast will be able to decipher what is written upon the parchment?>", completion = "What have you found, traveler? Ah, a scroll written in a mysterious language. Quite an interesting find!\n\n<Nola carefully examines the scroll.>\n\nI've never seen characters like these before, but perhaps Kugro has...", objectives = "Take the scroll to the tortollans along the Windswept Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49846] = { id = 49846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wars on Two Fronts", description = "{name}! You have been called upon once again to assist the Horde in matters of great import.\n\nWill you assist the Horde's efforts against Deathwing and the Twilight Hammer?\n\nOr will you fly south to Pandaria, claiming its resources before the Alliance does first?\n\nMake your choice and head into battle!", objectives = "Use the Special Duty Assignments to select your next adventuring destination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49851] = { id = 49851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm First Responder", description = "Deathwing, the draconic aspect of death, has sent his minions out to scour Azeroth of life.\n\nFarseer Krogar in Orgrimmar can tell you more about Mount Hyjal, Vashj'ir, and other areas that Deathwing has targeted.", completion = "Ah, {name}. Thank you for responding to my request.", objectives = "Report to Farseer Krogar in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49852] = { id = 49852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Pandaria!", description = "You are hereby ordered to present yourself at Grommash Hold immediately.\n\nWe have received word of a new, resource-rich continent in the south, and we intend to send you and a small contingent of soldiers to claim it for the Horde.", completion = "Lok'tar, {name}.", objectives = "Report to Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49855] = { id = 49855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disaster at Mount Hyjal", description = "Our brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nYou can speak with Cenarion Emissary Blackhoof to gain entry into Moonglade. He is in the tauren district in the Valley of Wisdom in Orgrimmar.", completion = "We knew the Horde would send help and not a moment too soon!", objectives = "Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49860] = { id = 49860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventure Calls", description = "Tales of your heroism have spread to the ends of Azeroth... and beyond. Your skills have been requested elsewhere.\n\nWill you travel through the Dark Portal, fighting the Burning Legion on the sundered world of Outland?\n\nOr will you fly north, joining the battle against the Lich King in Northrend?\n\nThe choice is yours, adventurer.", objectives = "Use the Special Duty Assignments to select your next adventuring destination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49862] = { id = 49862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: To Outland!", description = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the draenei. Adventurers of the Alliance are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion.\n\nTravel to the Blasted Lands, and pass through the Dark Portal.", objectives = "Go through the Dark Portal in Blasted Lands.\n\nThe Honor Hold Mage in the Mage District can help you get there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49863] = { id = 49863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: To Northrend!", description = "The Lich King stirs in the north.\n\nAn undead army follows his command, marching across Northrend and spreading blight wherever they tread.\n\nWe need you to stop them, {name}.", objectives = "Take a ship to Northrend.\n\nYou can board the ship to Borean Tundra in Stormwind Harbor, or the ship to Howling Fjord in Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49864] = { id = 49864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wars on Two Fronts", description = "{name}! You have been called upon once again to assist the Alliance in matters of great import.\n\nWill you assist the Alliance's efforts against Deathwing and the Twilight Hammer?\n\nOr will you fly south to Pandaria, claiming its resources before the Horde does first?\n\nMake your choice and head into battle!", objectives = "Use the Special Duty Assignments to select your next adventuring destination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49865] = { id = 49865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm: First Responder", description = "Deathwing, the draconic aspect of death, has sent his minions out to scour Azeroth of life.\n\nNaraat the Earthspeaker can tell you more about Mount Hyjal, Vashj'ir, and other areas that Deathwing has targeted.", completion = "Ah, {name}. Thank you for responding to my request.", objectives = "Report to Naraat the Earthspeaker in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49866] = { id = 49866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: To Pandaria!", description = "Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn.\n\nWe have received word of a conflict in the seas to the south, and we need the help of an experienced {class} to assist in the investigation.", completion = "Greetings, {name}.", objectives = "Report to Rell Nightwind in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49869] = { id = 49869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Defense", description = "The soldiers garrisoned here are doing their best to hold out, but they're struggling. Pirates haven't dared attack this gate in years, and never with such a large force.\n\nIf you're handy in a fight, Lieutenant Tarenfold will want to meet you. \n\nHe's organizing the militia up ahead.", completion = "Aha! Reinforcements!\n\nWait... Where are the rest of you?", objectives = "Report to Lieutenant Tarenfold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49870] = { id = 49870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Size Matters", description = "So the unintended side-effect of Gentle Ben'jin being, shall we say 'fun-sized' is that he is now small enough to get into the cave where the alpha wind serpent is! \n\nThe beast is called Gloomtail and if Ben'jin defeats it, he will feel like this territory is his and will want to fill it with little brutosaurs. So he will seek out a mate. If Maka'fon is receptive, everyone wins! \n\nGo give him another hit of the formula!", progress = "Size isn't all dat matters. Ben'jin can get to more places if he's small... and fight dere!", completion = "Dat was incredible! I could hear de snorting and stomping from here. \n\nWell done, {name}.", objectives = "Administer the 'voodoo'-ed Aggression Formula to Ben'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49871] = { id = 49871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Tide", description = "De mogu are growin' desperate. Ha! Maybe dey hope to get away from here before de fury of de loa rain down on dem!\n\nDe warlord's pet sorcerer set up blockers and dey have taken de tower.\n\nIf you can avoid the sting, de lightning rods can have ya feelin' pretty good. One could even say energized. \n\nGet to Warlord Xiar and relieve him of his life privileges.\n\nThen let our people know we have taken back de Breath of Pa'ku! \n\nDis mojo is empowered to ignite de tower with a mighty blast.", completion = "Not bad, {name}! Our work is nearly complete!", objectives = "Kill Warlord Xiar, and light the signal fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49873] = { id = 49873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacrificial Writes", description = "<As you peer inside the tome, you find a verse appear, glowing bright red.>\n\n\"For blood to bond, one strikes a deal,\nA sacrifce which will appeal.\nSeek out the lame, and never yield,\nFor in return, you shall be healed.\"\n\n<As you finish reading the verse, you notice that a scroll has appeared in your hand.\n\nWritten across the top it's titled, \"Writ of Sacrifice\". Various runes, unknown to you, appear on the rest of the scroll. Yet, there's no explanation as to what to do with the scroll...>", completion = "I see you've completed the trial.\n\n<Kronah takes the writ from your hand and places it on the tome. It slowly begins to meld with the tome, and in a burst of light it vanishes.>\n\nYou have done well and are now imprinted for all time with the Contract of Sacrifce.\n\nNow, onto more important matters. What do you think of murloc brain soup? I find it delightful and would love a guest to accompany me for a serving of it.", objectives = "Ask Kronah about the Writ of Sacrifice. Follow her directions after she gives you the information you need.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49874] = { id = 49874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Book", description = "As you open the book, you stare at a blank page, waiting for something to happen.\n\nInstinctively you flip to the next page only to find it blank as well. Perhaps your trial awaits you further into the book?", progress = "I trust you to be careful inside the Bloodshed Compendium. I don't want to find any ripped pages from that weapon you wield.", completion = "You've done well, young one. I recall a gnome not too long ago completing that trial as well.\n\nHer story was quite the read. But between you and me, gnomes smell like porridge.\n\n<Kronah looks off into the distance, lost in thought for a moment.>\n\nBut you are now a bearer of the Bloodshed Contract and one step closer to your final prize.\n\n<Kronah quirks a grin at you and goes back about her business.>", objectives = "Investigate the Bloodshed Compendium further to begin your trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49875] = { id = 49875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Impressions", description = "This was all I had to offer you, young scribe. But your journey is not yet at the end.\n\nGo to your trainer and and inform them of your success here.\n\n<Kronah grabs an odd-looking jar.>\n\nI don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you?\n\n<As she unlocks the lid, the foulest odor you've ever smelled permeates the air and you reel back in disgust.>\n\nFine, be that way. It's an acquired taste anyway. Takes thousands of years to train the palate.", sourceObjective = "Return to Zooey Inksprocket in Tiragarde Sound.", sourceObjectiveStatus = "unverified-source-field" }
quests[49876] = { id = 49876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lines In the Sand", description = "This was all I had to offer you, young scribe. But your journey is not yet at an end.\n\nIf you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar.\n\nOnce there, seek out a sethrak by the name of Veriss in an area known as Vol'dun.\n\n<Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.>\n\nPickled crocolisk eggs are my favorite. Would you like some?", completion = "Ah! A new initiate! Were you wondering how I knew? Because of the blood on your hands, of course.\n\n<A sly grin crosses over the sethrak's face.>\n\nI am Veriss, the resident keeper of the Zandalar blood contracts.\n\nIf you wish to inscribe your name into them, there is something I must ask of you first.", objectives = "Seek out Veriss at the Terrace of the Devoted in Vol'dun to begin your blood trials there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49877] = { id = 49877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of Sethraliss: Booking on a Favor", description = "When the Faithless came to power, we Devoted fled our sacred temple and took shelter here.\n\nHowever, in the midst of  our exodus, many of us were forced to abandon some of our belongings.\n\nI myself left a tome that is used to learn the Oblivion contract. If you wish to proceed with the trials, you must retrieve that book for me, {name}.\n\nI trust you won't disappoint me.", progress = "I'll admit, I'm a bit embarrassed to have left it behind. An oversight that I still regret to this day.", completion = "I'm relieved you were able to retrieve it. Thank you, {name}.", objectives = "Recover the Tome of Oblivion from the Temple of Sethraliss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49878] = { id = 49878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penning In Protection", description = "<As you open the book, you turn each page and see portraits of champions standing alongside a large beast.\n\nEventually you come to a blank portrait, and touch the page. Runes begin to appear in an ancient language, and quickly translate into words you can read.>\n\n\"The creature within, a guardian of men,\nA mixture of blood\nand of bone inked with pen.\nThe blood from the scribe,\nthe bone from the land,\nMilled to perfection,\nand signed by the hand.\"", progress = "You would think with all the blood you have to give up for these trials, that you would be white as a ghost at the end of them.\n\nOr maybe just passed out for a week.", completion = "You've been accepted, it appears.\n\n<Veriss motions to the book. You glance over and see an image of yourself posed alongside a great beast. Your signature glistening at the top of the page.>\n\nYou may now invoke the Contract of the Bloodguard.\n\nBe mindful of the guardian's life though. If it gets too low, it may look at you as potential fuel.", objectives = "Collect bones from Zem'lan pirates and mill them into a fine powder. Mix the powder with your blood to create a Vial of Ossein Ink. Then sign the Bloodguard Chronicles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49879] = { id = 49879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brush With Death", description = "<As you open the book, a sudden chill comes over you. You shake the sensation off as you read the verse.>\n\n\"A fatal bargain, in blood is struck,\nOne inks their pledge,\nwith strokes of luck.\nStay true your lines,\nkeep still your breath,\nLest you stray too far,\nand summon death.\"\n\n<As you finish reading the incantation, a quill appears next to the book.>", completion = "Well done, young blood scribe.\n\nYou can now invoke the Oblivion Contract. It lets you summon a creature that, well let's just say, his bite is bigger than his bark.\n\nHe likes to prey on creatures that are on the verge of death, yourself included if you're not too careful.", objectives = "Pick up the quill and begin your trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49880] = { id = 49880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Bonded", description = "Looks like you're all done here, {name}. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that.\n\nBut between you and me, this was the easy part. Just wait till you meet the grandmaster.\n\nI'll let your current trainer fill you in on that part. Good luck, {name}!", sourceObjective = "Return to Zooey Inksprocket in Tiragarde Sound.", sourceObjectiveStatus = "unverified-source-field" }
quests[49881] = { id = 49881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Verse", description = "It appears you are finished here, {name}. Thank you again for getting my book back.\n\nBut between you and I, this was the easy part. Just wait till you meet the grandmaster.\n\nIf you haven't noticed already, you'll need a special quill to invoke those contracts. And he'll be the one who shows you how to craft it.\n\nHis name is Miju and he lives out on an island off the southern coast of Zuldazar. Good luck, {name}!", completion = "What's this then? Another novice come to learn the ways of blood-scribing?\n\nVery well, for which contract do you need a quill?\n\n<You explain to Miju that you've learned all four contracts and need a quill to invoke all of them.>\n\nALL FOUR?! Oh my, it's been... let's see here...\n\n<Miju beings mumbling to himself.>\n\nToo long I suppose. But yes. I still know the recipe. Your trial awaits you then.", objectives = "Seek out Miju in southern Zuldazar to begin your final trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49882] = { id = 49882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Quills", description = "The recipe you're after, young one, is that of the Sanguine Feather Quill of Lana'thel. I...\n\n<Miju motions to a pile of stuff.>\n\nAm the only other person I know of who has one... err... somewhere. But be warned, this trial may be your undoing!\n\nI shall have to invoke all four contracts against you. You must defeat each of the creatures, and from each one learn the rune needed to carve into your quill.\n\nOnce you've learned all four runes, your trial shall be completed.", completion = "Well done, young scribe. Well done, indeed!\n\nYou have the knowledge now. It's up in there.\n\n<Miju tries to poke you in the head but you back away just in time.>\n\nYou're quick, probably how you succeeded in the trial. And now I present you with the final knowledge you need to craft your quill.\n\nOk, goodbye.", objectives = "Speak with Miju to begin your final trial and collect the knowledge to craft your quill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49884] = { id = 49884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope's Blue Light", description = "There is but one step left!\n\nDe second tower means the fleet is ours again!\n\nClimb aboard and we will finish dis thing!", completion = "You have saved de fleet and protected de Bay of Kings!\n\nYa did well, {name}! We captains are a wise lot.", objectives = "Fly with Captain Grez'ko to light the signal fire on the tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49886] = { id = 49886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow Your Nose", description = "You there! I could use your help!\n\nThe ground isn't safe. The quilboar have established a network of tunnels below us, allowing them to spring up to ambush people who aren't walking carefully.\n\nLuckily for us, Humphrey here has a nose for the Briarback, and can sniff 'em out even when they're underground. Root a few of them out and let's make the farms a little safer to walk through.\n\nThere's a particularly large clump of them in the northeastern fields. Good hunting!", completion = "Hah! I bet ol' Humphrey gave them a good spook!", objectives = "Use Humphrey to find and slay 5 Panicked Tunnelers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49887] = { id = 49887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forced Labor", description = "<The laborer struggles to speak through the magic binding him.>\n\nH... help... us...\n\n<He achingly lifts a finger, gesturing towards the nearby anchor.>\n\nPlease...", progress = "<It appears he lacks the energy to respond further.>", completion = "At least not all of the tidesages have turned on us.\n\nNot yet.", objectives = "Free Samuel Williams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49888] = { id = 49888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: A Little Mojo" }
quests[49890] = { id = 49890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drustfall", description = "I believe I see more carvings at the entrance to that cave over there. Come, we should see what else was left behind.", completion = "The carvings could have been Drust propaganda stating he lived, but that voice!\n<Cleardawn's face becomes grim>\nIt seems we may have all been mistaken about the ultimate fate of Gorak Tul. I shudder to think what he might be planning now.", objectives = "Investigate the ice cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49896] = { id = 49896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Falconhurst!", description = "Our time here was well spent. The guards in Arom's Stand can handle what few Drust forces remain and I suspect the Drust leader and his magic might have some greater part to play here. \n\nHowever we must continue on the mission to Falconhurst. The path on the far side of these ruins will take us there.\n\nI will ride ahead and meet you outside of town!", completion = "The town is under siege! No wonder we have not heard from them. We must help them.", objectives = "Meet Inquisitor Cleardawn outside of Falconhurst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49897] = { id = 49897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Mysteries", description = "Do you know what people love? The unexplained! Problem is, everything here is explainable. \n\nSo I have a plan to create our own phe-gnome-enon. There are stories that talk about some weird chicken-snake hybrids that can turn you to stone. I've already released the chickens, now we just need the snakes.\n\nThe first problem can be solved easily. Just chase down the chickens, and stick one of these robotic tails on them.", progress = "How do my petrifyingly scary chickens look?", completion = "Stupendous! Now we can start calling our resort tour a \"mystery safari\"!", objectives = "Catch 5 Unassuming Chickens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49898] = { id = 49898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear Victory", description = "<The ghostly captain continues to fight as she speaks, once more locked into the heat of battle, unaware the war has been over for centuries.>\n\nWhat are you doing standing around? We've ground them down to their final warriors and those damnable runic constructs, but the war isn't over yet!\n\nColonel Waycrest needs us to hold this line! Kill as many of those Drust as you can and we might see the end of this war, today. Get back out there!", completion = "Not bad, marine! We might make a proper soldier out of you yet!\n\nThey'll make Colonel Waycrest a Lord for this, I'm sure. Your bravery will be remembered.", objectives = "Slay 15 Drust Skeletons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49901] = { id = 49901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Yazma the Fallen Priestess", description = "Zul knows dat we cannot let de first king rise from his grave. Dazar would be more than a figure head for Zul's dream troll empire, he would be a force dat could rival de very loa.\n\nBut I cannot just let Zul get away. I and mine will follow Zul, but I want you and yours to enter Atal'Dazar. Yazma is trying to buy time and keep de tombs sealed away. You will need to fight your way through to her and you will need some allies to do so. Slay her.", progress = "And here I always thought Yazma was just rude. I never expected just how far she had fallen.", completion = "Yazma's betrayal was vile beyond words.\n\nIt may take us some time to find our way deeper into Atal'dazar. In de meantime, we have more work to do.", objectives = "Defeat Yazma in Atal'Dazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49902] = { id = 49902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Gloom Hollow", description = "There's only one safe area in Nazmir that this Rokhan and your other Horde friends could be in. Gloom Hollow.\n\nLucky for you, it's also close to Krag'wa's den. We used Gloom Hollow as a last stop on our pilgrimage.\n\nMake your way to Gloom Hollow along the path I've marked on your map, and tell any tortollans along the way to meet us there.\n\nThey'll be interested in seeing the end of this story. We'll make our way there and grab anyone else we find.", completion = "Good ta see ya, {name}. Princess Talanji be tellin' me all about Torga and da tortollans. Guess we lucky dat we got sometin' outta dis.\n\nWe be here, waitin' on reinforcements from da Horde.", objectives = "Recruit tortollans to your cause on the way to Gloom Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49905] = { id = 49905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plot Twist", description = "It is time to end Vol'jamba.\n\nI want to make one thing clear. He can still kill you. Your fate, moreso than mine, hangs on your ability to fight dis former student of mine.\n\nHe will bring masks, and voodoo, and he will do everything within his power to end you. All we have done is taken away his ability to cheat.\n\nGood luck. For your sake, I hope you do not fail.", progress = "Let us be rid of dis nuisance.", completion = "Death is a tool, {name}. Do not forget dat.", objectives = "Slay Vol'jamba.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49908] = { id = 49908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Brennadam", description = "The naga are mostly cleared out thanks to your help. They'll think twice before attacking again.\n\nCan you return to Brennadam and tell Squire Augustus III to return to his normal station?", completion = "Oh, roger! I'll head back at once!", objectives = "Report back to Squire Augustus III at Brennadam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49917] = { id = 49917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'mite? Kaja'must!", description = "I been waitin' to talk to the King for a while now, but he not be seein' me! And this pompous lackey not be listenin' either.\n\nWe got a problem brewin' in the Village of the Vines, just outside de city. With all the Horde landin' in the Harbor, some goblins got wind of our old kaja'mite quarry. They split outta here like the teeth of Deathwing himself behind 'em.\n\nBut that quarry be dangerous. Wicked dangerous. Think you can go to de village an' talk some sense into them goblins?", completion = "You came just in time pal. There's loads of work to do if there's really kaja'mite here in Zuldazar!", objectives = "Travel to Village in the Vines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49918] = { id = 49918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorilla Gorge" }
quests[49919] = { id = 49919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'mite Ore Bust", description = "Kaja'mite! Just saying the name gives my big beautiful ears a buzz. \n\nThese Zandalari were sitting on a huge deposit of it all these years. And they abandoned it just because of a few talking gorillas. By goblin law it's ours for the taking!\n\nLet's see how concentrated a deposit we're talking about. Get a good peek at those vents that are steaming out kaja'mite vapors.\n\nGo into the gorge and plant my scanners on those steam vents. They'll do the rest.", completion = "Thank you chump! I mean chum.\n\nThere's enough kaja'mite there to get us started. Too bad about all the talking gorillas in the way.", objectives = "Scan Kaja'mite Steam Vents in Gorilla Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49920] = { id = 49920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorilla Warfare", description = "Your timing is most fortuitous, stranger. I thank you for your assistance.\n\nThings are not peaceful in Gorilla Gorge. The kaja'mite has given us great intelligence and wit. With intelligence has come war. \n\nMy brethren are those who do not wish to fight. Neither the Zandalari trolls nor each other. But for our passivity we have been persecuted.\n\nPlease free my comrades. They will be in cages all throughout the gorge and under guard. Make haste!", completion = "Thank you my friend! I saw the bravery with which you granted freedom to my comrades. We shall speak more anon.", objectives = "Rescue 6 Pacifist Gorillas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49922] = { id = 49922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King Da'ka", description = "These Zandalari won't go near Gorilla Gorge. All because they're afraid!\n\nIt's just a few talking gorillas. And one 'big mon' in particular as the Zandalari call him. \n\nAll we need to do is take out King Da'ka and the villagers will probably throw us a parade! Or at least let us mine that kaja'mite.\n\nThink you can handle one big gorilla, chum?", completion = "Good. One less mook to deal with. That kaja'mite is as good as ours!", objectives = "Slay King Da'ka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49926] = { id = 49926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Corlain", description = "Lord and Lady Waycrest lay trapped in Waycrest Manor. Before we can reach them, however, we must brave through the city of Corlain... which is firmly in the grasp of the Heartsbane.\n\nOur first course of action should be to set up a forward outpost. Our scouts have found that the tower at Watchman's Rise is only lightly guarded. I recommend we take the tower from them.\n\nThis is now your command, Inquisitor. Say the word, and we ride.", completion = "Good, you've arrived. \n\nThis tower watches over Corlain and the surrounding lands. Apparently it is of little value to the coven, but to us it would serve as a valuable foothold.", objectives = "Meet with Marshal Reade at Watchman's Rise in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49928] = { id = 49928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Void", completion = "Though some continue to doubt us, your deeds have proven that the ren'dorei serve the Alliance with honor.\n\nYour will is strong, {name}. Accept this gift as a symbol of the powers you command.", objectives = "Meet Alleria Windrunner at Telogrus Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49929] = { id = 49929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call for Allies", description = "The Alliance has been beset by dangers growing throughout all of Azeroth.\n\nThe only way we will keep our friends safe is if we seek out new allies.\n\nI have been tasked as an ambassador to help seek these allies. Come to our embassy in Stormwind, I could use your help.", completion = "Welcome, {name}. I am pleased you answered the call.", objectives = "Meet Aysa Cloudsinger at the Stormwind Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49930] = { id = 49930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call for Allies", description = "Greetings, champion! I have been appointed as the Horde's diplomatic ambassador to our allies far and wide. \n\nIt is my duty to seek out those of like mind and spirit, and speak to them about joining the Horde.\n\nAs a renowned hero of the Horde yourself, your aid would be most appreciated! Come see me at the embassy in Orgrimmar when you are able.", completion = "Ah, {name}. Now we can begin.", objectives = "Meet Ji Firepaw at the Orgrimmar Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49931] = { id = 49931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Titan's Wrath" }
quests[49932] = { id = 49932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slumber No More", description = "There's something you should look into. You've got the time anyway, those goblins aren't ready yet.\n\nThere's a statue nearby. Only, it's not a statue to the trained tortollan eye. It's a deactivated titan keeper!\n\nNoises have been coming from that thing ever since you helped Krag'wa. It must be trying to reactivate itself.\n\nI bet that titan-looking amulet of yours could help restart it. We'd be unstoppable against the blood trolls with a titan keeper's help.\n\nGo see if you can restart this titan!", progress = "Core detected. Appreciation for retrieval.", completion = "Your aid is required. We must begin.", objectives = "Examine the deactivated titan keeper outside of Gloom Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49933] = { id = 49933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Horde", description = "After ages standing alone, we are once again poised to become part of something greater. Our alliance with the Horde affords us a fresh start, a unique chance that must not be squandered.\n\nGo to Orgrimmar. From there, you will set out on a journey across Azeroth. Fight to defend this land, and claim a place for the shal'dorei within it.\n\nShow the world who we are, {class}. Bring honor to the Horde, for in so doing, you will bring honor to Suramar.", completion = "Are you the new one? I'm supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>", objectives = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49935] = { id = 49935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Repair a Titan Keeper", description = "Major system repair possible within nearby structure. Preliminary goal: repair auxiliary systems.\n\nScans detect three fallen titan keepers. Recover cores. Titan Keeper Hezrel able to retrieve data from cores.\n\nTitan Keeper Hezrel goal: reboot auxiliary systems, reach nearby structure, restore all primary systems, seal corruption.\n\nResult: corruption contained. Titan Keeper Hezrel able to aid against blood trolls.\n\nBlood troll definition not found in databanks.", progress = "Insert data cores.", completion = "Cores recovered. Data validation and merge will begin shortly.", objectives = "Recover Titan Data Cores from fallen titan keepers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49937] = { id = 49937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering Remnants", description = "Scan of area indicates roaming spirits clad in armor plating. Purpose: defense of structure, animated by corruption.\n\nDetecting remnants of titan plating within spirits' armor. Request: recover remnants.\n\nTitan Keeper Hezrel capable of breaking down titan plating to reforge into weapon against forces drawn by corruption.", progress = "Titan plating required.", completion = "Sufficient titan plating. Will begin forging process once functionality is restored.", objectives = "Recover 25 Titan Plating from Nazwathan Spectres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49938] = { id = 49938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Earth", description = "Unacceptable levels of corruption detected nearby. Scan indicates vegetation affected by corruption. \n\nAll corruption must be eradicated. Request: destroy any vegetation affected by corruption.", completion = "Vegetation corruption reduced to an acceptable level.", objectives = "Destroy 12 Blood-Infused Lashers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49939] = { id = 49939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So Long, Sister", description = "We have given the defenders some breathing room, but these creatures continue to lay siege to the barricade!\n\nThe witch behind the attack fled from the field when we defeated her forces. I saw her go into the mansion on the hill. I will help keep the defenses going here.\n\nYou must go into the mansion and slay the witch!", progress = "The witch must be slain!", completion = "We wouldn't have been able to hold out much longer. You saved us all.", objectives = "Slay Sister Noella Briarwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49940] = { id = 49940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandscar Breach", description = "I heard some mutterings about sand and snakes.\n\nThe plea comes from a tiny village on the very fringes of Zuldazar- hardly more than a few farms. Dol-something I think it was called. Don't know what they be calling it now. Go see what the fuss is about.\n\nBladeguard Sonji was sent ahead some time ago. She should be able to get you up to speed on that... situation.", completion = "Rastakhan finally sent someone!\n\nI hope you not be afraid of snakes, mon.", objectives = "Meet Bladeguard Sonji at Sandscar Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49941] = { id = 49941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bone Procession", description = "Undead entities influenced by corruption surround nearby structure. Impossible to approach. Plan required.\n\nCalculating.\n\nPlan achieved. Large creatures designated reanimated monstrosities focal gathering point of corruption.\n\nTake titan weapon forged from plating recovered. Use it to weaken monstrosities and collect bones.\n\nWill run process to destroy bones, prevent creation of further monstrosities.", progress = "Insert reanimated monstrosity bones to continue.", completion = "Destruction of bones will begin.", objectives = "Weaken Reanimated Monstrosities with the Titan Manipulator and collect 15 of their bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49943] = { id = 49943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drawing Blood", description = "Hey, {name}! I have something exciting to tell you about, but I need you to keep it secret. Just between us scribes.\n\n<Grazzul gives you a nod and pulls out a large tome.>\n\nDis is de Bloodbound Ledger. Signing your name in it let's you learn how to craft \"blood contracts\" which are rather dangerous, but worth de risk.\n\nI only know one of dem and it is quite de rush when I use it because it... well, you'll see.\n\nSo what do you say? Interested?", completion = "Let me make sure you did it right.\n\n<Grazzul finds your signature and nods.>\n\nYes, everything looks in order and it looks like de spell has already taken effect on you.\n\nYou are now worthy of knowing how to craft de \"blood contracts\".\n\nBut be careful with dem, {name}. I said it before and I'll say it again. They're dangerous things to play with.", objectives = "Sign the Bloodbound Ledger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49944] = { id = 49944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn to Drust", description = "Dere are blood scribe masters all over de place who'll teach you what you need to know. De first master I'd recommend seeking out is Kronah.\n\nShe's a bit... eccentric to say de least. One of de few tortollan who've experienced a thing or two.\n\nShe's de one who taught me de blood contract I know how to invoke!\n\nShe prefers to hang out at de Smuggler's Cove on de western coast of Drustvar.", completion = "<Kronah eyes you up and down warily.>\n\nSay ahhh for me, would you lad?\n\n<Kronah peers inside your mouth.>\n\nNice teeth you have there. Would fetch a fine price. But that's not really what you're here for, is it?\n\nNo, you're one of those who think they can handle the trials of the blood contracts, aren't you? Very well.", objectives = "Seek out Kronah at the Smuggler's Cove in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49945] = { id = 49945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Impressions", description = "This was all I had to offer you, young scribe. But your journey is not yet at the end.\n\nGo to your trainer and and inform them of your success here.\n\n<Kronah grabs an odd-looking jar.>\n\nI don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you?\n\n<As she unlocks the lid, the foulest odor you've ever smelled permeates the air and you reel back in disgust.>\n\nFine, be that way. It's an acquired taste any ways. Takes thousands of years to train the palette.", objectives = "Return to Zooey Inksprocket in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49946] = { id = 49946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lines In the Sand", description = "This was all I had to offer you, young scribe. But your journey is not yet at an end.\n\nIf you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar.\n\nOnce there, seek out a sethrak by the name of Veriss in an area known as Vol'dun.\n\n<Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.>\n\nPickled crocolisk eggs are my favorite. Would you like some?", completion = "Ah! A new initiate! Were you wondering how I knew? Because of the blood on your hands, of course.\n\n<A sly grin crosses over the sethrak's face.>\n\nI am Veriss, the resident keeper of the Zandalar blood contracts.\n\nIf you wish to inscribe your name into them, there is something I must ask of you first.", objectives = "Seek out Veriss at the Terrace of the Devoted in Vol'dun to begin your blood trials there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49947] = { id = 49947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Bonded", description = "Looks like you're all done here, {name}. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that.\n\nBut between you and me, this was the easy part. Just wait till you meet the grandmaster.\n\nI'll let your current trainer fill you in on that part. Good luck, {name}!", sourceObjective = "Return to Zooey Inksprocket in Tiragarde Sound.", sourceObjectiveStatus = "unverified-source-field" }
quests[49948] = { id = 49948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Verse", description = "Now dat you be done learnin' all da contracts, you be needin' one more ting ta learn.\n\nDere be a special quill ya need to make in order to craft da contracts. And dere be one last trial ya must complete in order ta be worthy ta learn da design for da quill.\n\nMiju be da mastah in charge of da design. Pass his trial, and he'll be teachin' ya what'cha need ta know.", sourceObjective = "Seek out Miju in (Zone) to begin your final trial.", sourceObjectiveStatus = "unverified-source-field" }
quests[49949] = { id = 49949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Undead", description = "Corruption reanimating dead creatures nearby. Morphing into monstrosities. Must be stopped.\n\nCannot kill all, but can reduce numbers. Reduced numbers equates to less corruption outside of containment.\n\nDestroy undead in surrounding area. Keeper Hezrel's systems will continue rebooting while you do so.\n\nReboot goal: recover data regarding nature of corruption.", completion = "Undead levels lowered to acceptable amount. Still require method to bypass targets in order to access containment.", objectives = "Kill 15 Nazwathan undead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49950] = { id = 49950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Purification", description = "<You see a strange blood orb that emanates whispers of suffering and destruction.\n\nThese must be the source of energy for whatever corruption Hezrel is hunting. They appear easy enough to destroy.\n\nYou can see more of these orbs around the temple grounds. Perhaps destroying them will help to weaken the corruption in the area.>", completion = "Scanners did not pick up evidence of corrupted energy. Must continue repairs, cannot make same mistake again.", objectives = "Destroy 4 Corrupted Energy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49952] = { id = 49952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of G'huun", description = "Analysis of blood-infused bones complete. Will be able to create synthetic essence similar to G'huun.\n\nWill take a moment to apply essence, allow you to walk past undead without combat.\n\nMust hurry. More forces of G'huun are around temple. Must get inside to reactivate containment protocols.", objectives = "Have Titan Keeper Hezrel apply Synthetic Essence to allow safe passage past undead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49955] = { id = 49955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Fit for This Plane", description = "System restoration in progress. Data recovered. Source of corruption is from an Old God entity.\n\nMultiple entities detected nearby, blocking goal of analyzing and containing corruption in Nazmir.\n\nEntities appear to be from the Void. Drawn here from Old God corruption.\n\nRequest to destroy Void entities. Void presence inhibiting repair of systems.", progress = "Level of Void entities too high.", completion = "Old God minions temporarily reduced. Will not last long without proper containment.", objectives = "Eliminate 6 Faceless Ones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
